-- ---------------------------------------------------------------- hdr_pre_upgrade.sql
BEGIN
  BEGIN
    DBMS_SCHEDULER.DISABLE('HDR_TICK', force => TRUE);
    DBMS_SCHEDULER.STOP_JOB('HDR_TICK', force => FALSE);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE NOT IN (-27475, -27476, -27366) THEN   -- no such job / not running
      RAISE;
    END IF;
  END;
  BEGIN
    EXECUTE IMMEDIATE q'[MERGE INTO HDR_SETTINGS t USING (SELECT 'maintenance' k FROM DUAL) s ON (t.SKEY = s.k)
                         WHEN MATCHED THEN UPDATE SET SVALUE = 'Y'
                         WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, 'Y')]';
    COMMIT;
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE <> -942 THEN   -- a first install: no settings yet
      RAISE;
    END IF;
  END;
END;
/

-- ---------------------------------------------------------------- hader_interface.sql
DECLARE
  n NUMBER;
  m NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_PUNCHES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_PUNCHES (
        PUNCH_ID      NUMBER(12)     NOT NULL,          -- Hader's punch number (unique)
        EMP_CODE      VARCHAR2(30)   NOT NULL,          -- employee number on the terminal
        PUNCH_TIME    DATE           NOT NULL,
        PUNCH_STATE   NUMBER(3),                        -- 0 in, 1 out, 2 break out, 3 break in, 4 OT in, 5 OT out
        STATE_NAME    VARCHAR2(30),
        VERIFY_TYPE   VARCHAR2(30),                     -- fingerprint, face, palm, card, password...
        DEVICE_SN     VARCHAR2(50),
        DEVICE_NAME   VARCHAR2(100),
        SOURCE        VARCHAR2(10),                     -- device / tcp / manual / import
        TEMPERATURE   NUMBER(4,1),                      -- the body temperature a thermal terminal took
        UPLOADED_AT   DATE,                             -- reached the server (the terminal's clock)
        ORIG_TIME     DATE,                             -- its time before a clock fix
        FIXED_AT      DATE,
        CREATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_PUNCHES_PK PRIMARY KEY (PUNCH_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_EMP_IX ON HADER_PUNCHES (EMP_CODE, PUNCH_TIME)';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_PUNCHES_TIME_IX ON HADER_PUNCHES (PUNCH_TIME)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_ATT_DAILY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_ATT_DAILY (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        ATT_DATE      DATE           NOT NULL,          -- the day (time part 00:00)
        STATUS        VARCHAR2(20),                     -- present, late, early, late_early, absent, leave,
                                                        -- holiday, off, incomplete, unscheduled, pending
        STATUS_AR     VARCHAR2(40),
        STATUS_EN     VARCHAR2(40),
        TIMETABLE     VARCHAR2(60),
        SCHED_IN      DATE,
        SCHED_OUT     DATE,
        CLOCK_IN      DATE,
        CLOCK_OUT     DATE,
        REQUIRED_MIN  NUMBER(6),                        -- minutes the employee should have worked
        WORKED_MIN    NUMBER(6),
        LATE_MIN      NUMBER(6),
        EARLY_MIN     NUMBER(6),
        OT_MIN        NUMBER(6),
        LEAVE_MIN     NUMBER(6),
        ABSENT_DAYS   NUMBER(5,2),                      -- the day's share absent: 1 absent, less with leave or a partial absence
        ABSENT_MIN    NUMBER(6),                        -- minutes of absence
        LEAVE_CODES   VARCHAR2(100),
        HOLIDAY       VARCHAR2(100),
        PUNCHES       VARCHAR2(400),                    -- every punch of the day: 07:52 12:30 16:05
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_ATT_DAILY_PK PRIMARY KEY (EMP_CODE, ATT_DATE)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_ATT_DAILY_DATE_IX ON HADER_ATT_DAILY (ATT_DATE, STATUS)';
  END IF;
  -- added in version 1.5: tables created by an earlier script get it in place
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = 'ABSENT_MIN';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (ABSENT_MIN NUMBER(6))';
  END IF;
  -- 1.9.5: the body temperature a thermal terminal took (the punch log shows it)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'TEMPERATURE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (TEMPERATURE NUMBER(4,1))';
  END IF;
  -- 2.3.7: when the punch reached the server, on the terminal's clock (the punch log's "arrived after")
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'UPLOADED_AT';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (UPLOADED_AT DATE)';
  END IF;
  -- 2.3.8: a punch whose clock had gone back to midnight, corrected: the time the terminal gave it, and when
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_PUNCHES' AND column_name = 'ORIG_TIME';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_PUNCHES ADD (ORIG_TIME DATE, FIXED_AT DATE)';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_EMP_PHOTOS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_EMP_PHOTOS (
        EMP_CODE      VARCHAR2(30)   NOT NULL,
        PHOTO         BLOB,                             -- JPEG
        SOURCE        VARCHAR2(10),                     -- HAND / DEVICE: the card picture; CAPTURE: the recognition photo
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_EMP_PHOTOS_PK PRIMARY KEY (EMP_CODE)
      )]';
  END IF;
  -- added in version 1.6.6: the card picture (shown by the terminals) apart from the recognition photo
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_EMP_PHOTOS' AND column_name = 'SOURCE';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_EMP_PHOTOS ADD (SOURCE VARCHAR2(10))';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_REQUESTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_REQUESTS (
        REQ_ID        RAW(16)        DEFAULT SYS_GUID() NOT NULL,
        KIND          VARCHAR2(20)   NOT NULL,          -- SYNC, PUNCHES, EMPLOYEES, LEAVES, RECALC
        EMP_CODE      VARCHAR2(30),                     -- RECALC / SYNC: one employee only (optional)
        DATE_FROM     DATE,                             -- RECALC / SYNC / LEAVES: period (default today)
        DATE_TO       DATE,
        REQUESTED_BY  VARCHAR2(100),
        REQUESTED_AT  DATE DEFAULT SYSDATE NOT NULL,
        STATUS        VARCHAR2(10)   DEFAULT 'NEW' NOT NULL,   -- NEW, RUNNING, DONE, FAILED
        STARTED_AT    DATE,
        FINISHED_AT   DATE,
        MESSAGE       VARCHAR2(4000),
        CONSTRAINT HADER_REQUESTS_PK PRIMARY KEY (REQ_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_ST_IX ON HADER_REQUESTS (STATUS, REQUESTED_AT)';
  END IF;
  -- added in version 1.5.8: a request for one terminal (KIND = DEVICE)
  FOR c IN (SELECT 'DEVICE_SN' col, 'VARCHAR2(50)' def FROM DUAL                -- the terminal's serial number
            UNION ALL SELECT 'ACTION', 'VARCHAR2(30)' FROM DUAL                -- what to do (see HADER_DEVICES below)
            UNION ALL SELECT 'DETAIL', 'VARCHAR2(400)' FROM DUAL) LOOP          -- e.g. 9 face / 1 finger to enroll
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (' || c.col || ' ' || c.def || ')';
    END IF;
  END LOOP;
  -- added in version 1.8.0: the employee portal of APEX app 141 asks Hader for an employee's requests, balances and
  -- inbox (KIND = PORTAL; ACTION mine / leave / manual / overtime / cancel / read; DETAIL the fields as JSON in plain
  -- ASCII, so it may be long) and Hader answers in REPLY (JSON in plain ASCII)
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'REPLY';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS ADD (REPLY CLOB)';
  END IF;
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_REQUESTS' AND column_name = 'DETAIL'
     AND data_length < 4000;
  IF n > 0 THEN
    EXECUTE IMMEDIATE 'ALTER TABLE HADER_REQUESTS MODIFY (DETAIL VARCHAR2(4000))';
  END IF;
  SELECT COUNT(*) INTO n FROM user_indexes WHERE index_name = 'HADER_REQUESTS_EMP_IX';
  IF n = 0 THEN
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_REQUESTS_EMP_IX ON HADER_REQUESTS (EMP_CODE, KIND, REQUESTED_AT)';
  END IF;

  -- added in version 1.6.3, for reports that add up exactly as Hader's: the work days the day counts as,
  -- the share of them attended, the missing check-in / check-out, and the day's first and last punch
  m := 0;
  FOR c IN (SELECT 'WORKDAY' col, 'NUMBER(5,2)' def FROM DUAL UNION ALL SELECT 'PRESENT', 'NUMBER(5,2)' FROM DUAL
            UNION ALL SELECT 'MISSED_IN', 'NUMBER(2)' FROM DUAL UNION ALL SELECT 'MISSED_OUT', 'NUMBER(2)' FROM DUAL
            UNION ALL SELECT 'MISSED_LIST', 'VARCHAR2(200)' FROM DUAL UNION ALL SELECT 'FIRST_PUNCH', 'DATE' FROM DUAL
            UNION ALL SELECT 'LAST_PUNCH', 'DATE' FROM DUAL) LOOP
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_ATT_DAILY' AND column_name = c.col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE HADER_ATT_DAILY ADD (' || c.col || ' ' || c.def || ')';
      m := m + 1;
    END IF;
  END LOOP;
  IF m > 0 THEN   -- the days already there get them on their next calculation: this month and the last one now
    EXECUTE IMMEDIATE q'[INSERT INTO HADER_REQUESTS (KIND, DATE_FROM, DATE_TO, REQUESTED_BY)
                         VALUES ('RECALC', ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1), TRUNC(SYSDATE), 'install 1.6.3')]';
  END IF;

  -- the terminals, as Hader sees them (written every minute while APEX requests are on)
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICES (
        SN            VARCHAR2(50)   NOT NULL,
        NAME          VARCHAR2(100),
        AREA_NAME     VARCHAR2(100),
        IP            VARCHAR2(50),
        STATE         VARCHAR2(10),                     -- online, offline, disabled
        MODE_NAME     VARCHAR2(20),                     -- push (the terminal calls Hader) / direct (Hader reads it)
        LAST_CONTACT  DATE,
        LAST_UPLOAD   DATE,                             -- last time it sent punches or people
        MODEL         VARCHAR2(100),
        FIRMWARE      VARCHAR2(100),
        USER_COUNT    NUMBER(8),
        FP_COUNT      NUMBER(8),
        FACE_COUNT    NUMBER(8),
        PALM_COUNT    NUMBER(8),
        ATT_COUNT     NUMBER(10),
        PENDING       NUMBER(8),                        -- commands still owed to it
        READ_ONLY     CHAR(1),                          -- Y: Hader may not write to terminals now
        UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
        CONSTRAINT HADER_DEVICES_PK PRIMARY KEY (SN)
      )]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HADER_DEVICE_COMMANDS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE HADER_DEVICE_COMMANDS (
        CMD_ID        NUMBER(12)     NOT NULL,          -- Hader's command number
        DEVICE_SN     VARCHAR2(50)   NOT NULL,
        TITLE         VARCHAR2(120),
        STATUS        VARCHAR2(10),                     -- pending, sent, done, failed
        RETURN_CODE   VARCHAR2(20),                     -- the terminal's answer (0 = done)
        CREATED_AT    DATE,
        SENT_AT       DATE,
        RETURNED_AT   DATE,
        CONSTRAINT HADER_DEVICE_COMMANDS_PK PRIMARY KEY (CMD_ID)
      )]';
    EXECUTE IMMEDIATE 'CREATE INDEX HADER_DEVICE_COMMANDS_SN_IX ON HADER_DEVICE_COMMANDS (DEVICE_SN, CREATED_AT)';
  END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_REQUESTS_BY BEFORE INSERT ON HADER_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100);
  ELSIF :NEW.REQUESTED_BY IS NULL OR SYS_CONTEXT('USERENV', 'SESSION_USER') <> SYS_CONTEXT('USERENV', 'CURRENT_USER') THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('USERENV', 'SESSION_USER'), 1, 100);
  END IF;
END;]';
  -- made again over the table as it is now (columns added above): the same text alone would leave it as it was
  EXECUTE IMMEDIATE 'ALTER TRIGGER HADER_REQUESTS_BY COMPILE';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN   -- ORA-01031: this user may not create triggers
    RAISE;
  END IF;
END;
/
COMMENT ON TABLE HADER_PUNCHES IS 'Written by Hader: every punch from the terminals';
COMMENT ON TABLE HADER_ATT_DAILY IS 'Written by Hader: attendance result per employee per day (re-sent when it changes)';
COMMENT ON TABLE HADER_REQUESTS IS 'Written by APEX pages, answered by Hader: sync / recalculation / terminal requests';
COMMENT ON TABLE HADER_DEVICES IS 'Written by Hader: the terminals, their state and counts';
COMMENT ON TABLE HADER_DEVICE_COMMANDS IS 'Written by Hader: commands sent to the terminals in the last days and their answers';
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_DEPARTMENTS';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_DEPARTMENTS AS
      SELECT CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- unique code
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- Arabic name
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME_EN    -- English name (optional)
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_EMPLOYEES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_EMPLOYEES AS
      SELECT CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,       -- number used on the terminals
             CAST(NULL AS VARCHAR2(200)) AS FULL_NAME,      -- Arabic full name
             CAST(NULL AS VARCHAR2(160)) AS NAME_EN,        -- English name (optional)
             CAST(NULL AS VARCHAR2(50))  AS DEPT_CODE,      -- = HADER_V_DEPARTMENTS.DEPT_CODE
             CAST(NULL AS VARCHAR2(120)) AS DEPT_NAME,      -- (optional) used when the department is new
             CAST(NULL AS VARCHAR2(120)) AS POSITION_NAME,  -- job title (optional)
             CAST(NULL AS DATE)          AS HIRE_DATE,      -- (optional)
             CAST(NULL AS VARCHAR2(20))  AS STATUS,         -- A / ACTIVE / 1 = working; anything else = left
             CAST(NULL AS DATE)          AS RESIGN_DATE,    -- (optional)
             CAST(NULL AS VARCHAR2(30))  AS CARD_NO,        -- (optional) badge number
             CAST(NULL AS VARCHAR2(120)) AS EMAIL,          -- (optional) for alerts
             CAST(NULL AS VARCHAR2(50))  AS MOBILE,         -- (optional)
             CAST(NULL AS VARCHAR2(50))  AS AREA_CODE       -- (optional) Hader area = which terminals
        FROM DUAL WHERE 1 = 0]';
  END IF;

  SELECT COUNT(*) INTO n FROM user_views WHERE view_name = 'HADER_V_LEAVES';
  IF n = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE VIEW HADER_V_LEAVES AS
      SELECT CAST(NULL AS VARCHAR2(60))  AS LEAVE_ID,       -- unique id in your system
             CAST(NULL AS VARCHAR2(30))  AS EMP_CODE,
             CAST(NULL AS VARCHAR2(10))  AS LEAVE_CODE,     -- e.g. AL, SL
             CAST(NULL AS VARCHAR2(60))  AS LEAVE_NAME,
             CAST(NULL AS DATE)          AS START_TIME,     -- whole days: 00:00 of the first day
             CAST(NULL AS DATE)          AS END_TIME,       -- whole days: 00:00 of the day after the last
             CAST(NULL AS VARCHAR2(20))  AS STATUS          -- APPROVED / PENDING / REJECTED
        FROM DUAL WHERE 1 = 0]';
  END IF;
END;
/
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tables WHERE table_name = 'HDR_EMPLOYEES';
  IF n > 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, TO_NCHAR(e.FULL_NAME) AS FULL_NAME, TO_CHAR(e.NAME_EN) AS NAME_EN, e.DEPT_CODE,
             TO_NCHAR(d.NAME) AS DEPT_NAME, TO_CHAR(d.NAME_EN) AS DEPT_NAME_EN, TO_NCHAR(e.POSITION_NAME) AS POSITION_NAME,
             TO_CHAR(e.EMAIL) AS EMAIL, TO_CHAR(e.STATUS) AS STATUS
        FROM HDR_EMPLOYEES e LEFT JOIN HDR_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE
      UNION ALL
      SELECT TO_CHAR(h.EMP_CODE), TO_NCHAR(h.FULL_NAME), TO_CHAR(h.NAME_EN), TO_CHAR(h.DEPT_CODE),
             TO_NCHAR(NVL(hd.DEPT_NAME, h.DEPT_NAME)), TO_CHAR(hd.DEPT_NAME_EN), TO_NCHAR(h.POSITION_NAME),
             TO_CHAR(h.EMAIL), TO_CHAR(h.STATUS)
        FROM HADER_V_EMPLOYEES h LEFT JOIN HADER_V_DEPARTMENTS hd ON hd.DEPT_CODE = h.DEPT_CODE
       WHERE NOT EXISTS (SELECT 1 FROM HDR_EMPLOYEES x WHERE x.EMP_CODE = TO_CHAR(h.EMP_CODE))]';
  ELSE
    EXECUTE IMMEDIATE q'[
      CREATE OR REPLACE VIEW HADER_V_PEOPLE AS
      SELECT e.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE, NVL(d.DEPT_NAME, e.DEPT_NAME) AS DEPT_NAME,
             d.DEPT_NAME_EN, e.POSITION_NAME, e.EMAIL, e.STATUS
        FROM HADER_V_EMPLOYEES e LEFT JOIN HADER_V_DEPARTMENTS d ON d.DEPT_CODE = e.DEPT_CODE]';
  END IF;
END;
/
CREATE OR REPLACE VIEW HADER_V_ATT_REPORT AS
SELECT d.ATT_DATE, d.EMP_CODE, e.FULL_NAME, e.NAME_EN, e.DEPT_CODE,
       e.DEPT_NAME, d.STATUS, d.STATUS_AR, d.STATUS_EN, d.TIMETABLE,
       d.SCHED_IN, d.SCHED_OUT, d.CLOCK_IN, d.CLOCK_OUT, d.REQUIRED_MIN, d.WORKED_MIN, d.LATE_MIN,
       d.EARLY_MIN, d.OT_MIN, d.LEAVE_MIN, d.ABSENT_DAYS, d.ABSENT_MIN, d.LEAVE_CODES, d.HOLIDAY, d.PUNCHES, d.UPDATED_AT,
       -- the status as the program's reports write it: with the holiday's name and the leave codes
       d.STATUS_AR || CASE WHEN d.HOLIDAY IS NOT NULL THEN ' (' || d.HOLIDAY || ')' END
                   || CASE WHEN d.LEAVE_CODES IS NOT NULL THEN ' [' || d.LEAVE_CODES || ']' END AS STATUS_LABEL,
       d.FIRST_PUNCH, d.LAST_PUNCH,
       -- the work days the day counts as and the share attended (a day calculated before 1.6.3: by its status)
       NVL(d.WORKDAY, CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled', 'leave') OR d.STATUS IS NULL
                           THEN 0 ELSE 1 END) AS WORKDAY,
       NVL(d.PRESENT, CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
                           THEN 1 ELSE 0 END) AS PRESENT,
       NVL(d.MISSED_IN, 0) + NVL(d.MISSED_OUT, CASE WHEN d.MISSED_IN IS NULL AND d.STATUS = 'incomplete' THEN 1 ELSE 0 END)
         AS MISSED_PUNCHES,
       NVL(d.MISSED_IN, 0) AS MISSED_IN, NVL(d.MISSED_OUT, 0) AS MISSED_OUT,
       -- the missing punches as the program writes them (a split day can miss two)
       REPLACE(REPLACE(REPLACE(d.MISSED_LIST, 'missed_in', UNISTR('\0628\062F\0648\0646 \062F\062E\0648\0644')),
               'missed_out', UNISTR('\0628\062F\0648\0646 \062E\0631\0648\062C')), ',', UNISTR('\060C ')) AS MISSED_TEXT,
       -- 0/1 flags, so APEX pages never have to list statuses (sum them for counts and rates)
       CASE WHEN d.STATUS IN ('off', 'holiday', 'unscheduled') THEN 0 ELSE 1 END AS IS_EXPECTED,
       CASE WHEN d.STATUS IN ('present', 'late', 'early', 'late_early', 'incomplete', 'partial_absent')
            THEN 1 ELSE 0 END AS IS_PRESENT,
       CASE WHEN d.LATE_MIN > 0 THEN 1 ELSE 0 END AS IS_LATE,
       CASE WHEN d.EARLY_MIN > 0 THEN 1 ELSE 0 END AS IS_EARLY,
       CASE WHEN d.OT_MIN > 0 THEN 1 ELSE 0 END AS IS_OT,
       CASE WHEN d.STATUS = 'absent' THEN 1 ELSE 0 END AS IS_ABSENT,
       CASE WHEN d.STATUS = 'partial_absent' THEN 1 ELSE 0 END AS IS_PARTIAL,
       CASE WHEN d.STATUS = 'leave' THEN 1 ELSE 0 END AS IS_LEAVE,
       CASE WHEN d.STATUS = 'holiday' THEN 1 ELSE 0 END AS IS_HOLIDAY,
       CASE WHEN d.STATUS = 'off' THEN 1 ELSE 0 END AS IS_OFF
  FROM HADER_ATT_DAILY d
  LEFT JOIN HADER_V_PEOPLE e ON e.EMP_CODE = d.EMP_CODE;
CREATE OR REPLACE VIEW HADER_V_MONTH_SUMMARY AS
SELECT TRUNC(ATT_DATE, 'MM') AS MONTH_START, TO_CHAR(ATT_DATE, 'YYYY-MM') AS MONTH, EMP_CODE,
       MAX(FULL_NAME) AS FULL_NAME, MAX(NAME_EN) AS NAME_EN, MAX(DEPT_CODE) AS DEPT_CODE, MAX(DEPT_NAME) AS DEPT_NAME,
       SUM(WORKDAY) AS WORK_DAYS, SUM(PRESENT) AS PRESENT_DAYS, SUM(ABSENT_DAYS) AS ABSENT_DAYS,
       SUM(IS_ABSENT) AS ABSENT_WHOLE_DAYS, SUM(IS_PARTIAL) AS PARTIAL_ABSENT_DAYS, SUM(ABSENT_MIN) AS ABSENT_MIN,
       SUM(IS_LEAVE) AS LEAVE_DAYS, SUM(IS_LATE) AS LATE_TIMES, SUM(LATE_MIN) AS LATE_MIN,
       SUM(IS_EARLY) AS EARLY_TIMES, SUM(EARLY_MIN) AS EARLY_MIN,
       SUM(OT_MIN) AS OT_MIN, SUM(LEAVE_MIN) AS LEAVE_MIN, SUM(WORKED_MIN) AS WORKED_MIN, SUM(REQUIRED_MIN) AS REQUIRED_MIN,
       SUM(MISSED_PUNCHES) AS MISSED_PUNCHES, SUM(IS_HOLIDAY) AS HOLIDAYS, SUM(IS_OFF) AS OFF_DAYS,
       MAX(UPDATED_AT) AS UPDATED_AT
  FROM HADER_V_ATT_REPORT
 GROUP BY TRUNC(ATT_DATE, 'MM'), TO_CHAR(ATT_DATE, 'YYYY-MM'), EMP_CODE;

-- ---------------------------------------------------------------- hader_devices_link.sql
DECLARE
  n NUMBER;
  -- a table (or sequence) is made only when missing; its indexes with it
  PROCEDURE mk(p_name VARCHAR2, p_ddl VARCHAR2, p_ix1 VARCHAR2 DEFAULT NULL, p_ix2 VARCHAR2 DEFAULT NULL,
               p_ix3 VARCHAR2 DEFAULT NULL) IS
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name AND object_type IN ('TABLE', 'SEQUENCE');
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_ddl;
      IF p_ix1 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix1; END IF;
      IF p_ix2 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix2; END IF;
      IF p_ix3 IS NOT NULL THEN EXECUTE IMMEDIATE p_ix3; END IF;
    END IF;
  END;
BEGIN
  mk('HADER_DEV_SEQ', 'CREATE SEQUENCE HADER_DEV_SEQ START WITH 1 INCREMENT BY 1 NOCACHE');
  -- key/value facts: hader.beat (Hader's clock at each round), writing, link.*, set.<device setting> ...
  mk('HADER_DEV_STATE', q'[CREATE TABLE HADER_DEV_STATE (SKEY VARCHAR2(60) NOT NULL, SVALUE VARCHAR2(4000),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_STATE_PK PRIMARY KEY (SKEY))]');
  -- one row per terminal, as the program's device list shows it (never its comm key)
  mk('HADER_DEV_TERMINALS', q'[CREATE TABLE HADER_DEV_TERMINALS (SN VARCHAR2(50) NOT NULL, DEVICE_ID NUMBER(10) NOT NULL,
    NAME VARCHAR2(100), NAME_EN VARCHAR2(100), AREA_ID NUMBER(10), AREA_NAME VARCHAR2(120), IP VARCHAR2(50),
    STATE VARCHAR2(10), ACTIVITY VARCHAR2(12), REQUESTING_WHAT VARCHAR2(400), VIRTUAL_YN CHAR(1), READ_ONLY CHAR(1),
    CONNECTION_MODE VARCHAR2(10), STATUS_DETAIL VARCHAR2(400), DAY_RECON VARCHAR2(400), LAST_CONTACT DATE,
    LAST_UPLOAD DATE, LAST_INIT DATE, MODEL VARCHAR2(100), FIRMWARE VARCHAR2(100), PUSH_VER VARCHAR2(30),
    PLATFORM VARCHAR2(60), MAC VARCHAR2(30), FP_ALG VARCHAR2(20), FACE_ALG VARCHAR2(20), USER_COUNT NUMBER(8),
    FP_COUNT NUMBER(8), FACE_COUNT NUMBER(8), PALM_COUNT NUMBER(8), ATT_COUNT NUMBER(10), PENDING NUMBER(8),
    PEOPLE_EXPECTED NUMBER(8), ENABLED CHAR(1), IS_ATTENDANCE CHAR(1), IS_REGISTRATION CHAR(1), REALTIME CHAR(1),
    TCP_POLL CHAR(1), TIME_ZONE NUMBER(3), HEARTBEAT NUMBER(5), TRANS_INTERVAL NUMBER(5), TRANS_TIMES VARCHAR2(100),
    TCP_PORT NUMBER(6), ALLOWED_IPS VARCHAR2(400), WAITING_YN CHAR(1), MOVED_IP VARCHAR2(50), MOVED_AT DATE,
    MOVED_VIA VARCHAR2(20), BIO_SUPPORT VARCHAR2(400), ATT_STAMP VARCHAR2(30), OP_STAMP VARCHAR2(30), OPTIONS CLOB,
    ROW_HASH VARCHAR2(40), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_TERMINALS_PK PRIMARY KEY (SN))]');
  mk('HADER_DEV_AREAS', q'[CREATE TABLE HADER_DEV_AREAS (AREA_ID NUMBER(10) NOT NULL, CODE VARCHAR2(50),
    NAME VARCHAR2(120), NAME_EN VARCHAR2(120), DEVICES NUMBER(6), EMPLOYEES NUMBER(8),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_AREAS_PK PRIMARY KEY (AREA_ID))]');
  -- a card, password or privilege a terminal sent, waiting for a person (the value masked as the program shows it)
  mk('HADER_DEV_HELD', q'[CREATE TABLE HADER_DEV_HELD (HELD_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    EMP_CODE VARCHAR2(30), EMP_NAME VARCHAR2(200), FIELD VARCHAR2(20), VALUE_SHOWN VARCHAR2(60), HELD_AT DATE,
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_HELD_PK PRIMARY KEY (HELD_ID))]');
  mk('HADER_DEV_PEOPLE', q'[CREATE TABLE HADER_DEV_PEOPLE (EMP_CODE VARCHAR2(30) NOT NULL, NAME VARCHAR2(200),
    NAME_EN VARCHAR2(200), DEPT VARCHAR2(200), ACTIVE CHAR(1), AREA_IDS VARCHAR2(400), FACES NUMBER(3),
    FINGERS NUMBER(3), PALMS NUMBER(3), PHOTO_YN CHAR(1), ROW_HASH VARCHAR2(40),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_PEOPLE_PK PRIMARY KEY (EMP_CODE))]');
  -- the command log, its content and result redacted as the program's page shows them
  mk('HADER_DEV_COMMANDS', q'[CREATE TABLE HADER_DEV_COMMANDS (CMD_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    TITLE VARCHAR2(120), DIRECTION VARCHAR2(6), STATUS VARCHAR2(10), ATTEMPTS NUMBER(3), RETURN_CODE VARCHAR2(20),
    CONTENT_SHOWN VARCHAR2(200), RESULT_SHOWN VARCHAR2(400), REQ_ID NUMBER(12), CREATED_AT DATE, SENT_AT DATE,
    RETURNED_AT DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_COMMANDS_PK PRIMARY KEY (CMD_ID))]',
    'CREATE INDEX HADER_DEV_COMMANDS_SN_IX ON HADER_DEV_COMMANDS (SN, CREATED_AT)');
  mk('HADER_DEV_OPLOG', q'[CREATE TABLE HADER_DEV_OPLOG (LOG_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    OP_CODE NUMBER(6), ADMIN VARCHAR2(30), OP_TIME DATE, OBJ1 VARCHAR2(50), OBJ2 VARCHAR2(50), OBJ3 VARCHAR2(50),
    OBJ4 VARCHAR2(50), UPLOAD_TIME DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_OPLOG_PK PRIMARY KEY (LOG_ID))]');
  mk('HADER_DEV_ERRLOG', q'[CREATE TABLE HADER_DEV_ERRLOG (LOG_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    ERR_CODE VARCHAR2(20), ERR_MSG VARCHAR2(4000), UPLOAD_TIME DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_ERRLOG_PK PRIMARY KEY (LOG_ID))]');
  mk('HADER_DEV_TRAFFIC', q'[CREATE TABLE HADER_DEV_TRAFFIC (SEQ_NO NUMBER(12) NOT NULL, AT DATE, SN VARCHAR2(50),
    METHOD VARCHAR2(8), PATH VARCHAR2(200), QUERY_TEXT VARCHAR2(1000), BYTES NUMBER(10), REPLY_SHOWN VARCHAR2(1000),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_TRAFFIC_PK PRIMARY KEY (SEQ_NO))]');
  mk('HADER_DEV_RECENT_PUNCHES', q'[CREATE TABLE HADER_DEV_RECENT_PUNCHES (PUNCH_ID NUMBER(12) NOT NULL,
    SN VARCHAR2(50), EMP_CODE VARCHAR2(30), NAME VARCHAR2(200), PUNCH_TIME DATE, STATE_NAME VARCHAR2(40),
    VERIFY_NAME VARCHAR2(40), SOURCE VARCHAR2(10), UPLOADED_AT DATE, UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_RECENT_PUNCHES_PK PRIMARY KEY (PUNCH_ID))]');
  mk('HADER_DEV_INTAKE', q'[CREATE TABLE HADER_DEV_INTAKE (BATCH_ID NUMBER(12) NOT NULL, SN VARCHAR2(50),
    RECEIVED_AT DATE, ACCEPTED NUMBER(8), DUPLICATES NUMBER(8), REJECTED_OPEN NUMBER(8), REPLAYS NUMBER(8),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT HADER_DEV_INTAKE_PK PRIMARY KEY (BATCH_ID))]');
  -- the terminal-like panel: its saved values each round, the live ones when a panel_read is answered
  mk('HADER_DEV_PANELS', q'[CREATE TABLE HADER_DEV_PANELS (SN VARCHAR2(50) NOT NULL, LIVE_YN CHAR(1), BUSY_YN CHAR(1),
    READ_AT DATE, BODY CLOB, REQ_ID NUMBER(12), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_PANELS_PK PRIMARY KEY (SN))]');
  -- who may open which page (never trusted by Hader, and no secret in it)
  mk('HADER_DEV_USERS', q'[CREATE TABLE HADER_DEV_USERS (USERNAME VARCHAR2(100) NOT NULL, ACTIVE CHAR(1),
    IS_SUPER CHAR(1), PERMS VARCHAR2(1000), ADMIN_OK CHAR(1), UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT HADER_DEV_USERS_PK PRIMARY KEY (USERNAME))]');
  mk('HADER_DEV_REQUESTS', q'[CREATE TABLE HADER_DEV_REQUESTS (REQ_ID NUMBER(12) NOT NULL, BATCH_ID NUMBER(12),
    CATEGORY VARCHAR2(10) NOT NULL, ACTION VARCHAR2(40) NOT NULL, SN VARCHAR2(50), TARGET_ID NUMBER(12),
    PARAMS VARCHAR2(4000), REQUESTED_BY VARCHAR2(100), REQUESTED_AT DATE DEFAULT SYSDATE NOT NULL,
    STATUS VARCHAR2(10) DEFAULT 'NEW' NOT NULL, PICKED_AT DATE, FINISHED_AT DATE, HTTP_CODE NUMBER(4),
    MESSAGE VARCHAR2(4000), REPLY CLOB, CONSTRAINT HADER_DEV_REQUESTS_PK PRIMARY KEY (REQ_ID),
    CONSTRAINT HADER_DEV_REQUESTS_ST CHECK (STATUS IN ('NEW','RUNNING','DONE','FAILED','EXPIRED','CANCELLED')))]',
    'CREATE INDEX HADER_DEV_REQUESTS_ST_IX ON HADER_DEV_REQUESTS (STATUS, REQ_ID)',
    'CREATE INDEX HADER_DEV_REQUESTS_BATCH_IX ON HADER_DEV_REQUESTS (BATCH_ID)',
    'CREATE INDEX HADER_DEV_REQUESTS_BY_IX ON HADER_DEV_REQUESTS (REQUESTED_BY, REQUESTED_AT)');
END;
/
BEGIN
  FOR t IN (SELECT table_name FROM user_tables WHERE table_name IN ('HADER_DEV_STATE', 'HADER_DEV_TERMINALS',
              'HADER_DEV_AREAS', 'HADER_DEV_HELD', 'HADER_DEV_PEOPLE', 'HADER_DEV_COMMANDS', 'HADER_DEV_OPLOG',
              'HADER_DEV_ERRLOG', 'HADER_DEV_TRAFFIC', 'HADER_DEV_RECENT_PUNCHES', 'HADER_DEV_INTAKE',
              'HADER_DEV_PANELS', 'HADER_DEV_USERS')) LOOP
    EXECUTE IMMEDIATE 'CREATE OR REPLACE TRIGGER ' || SUBSTR(t.table_name, 1, 27) || '_RO BEFORE INSERT OR UPDATE OR DELETE ON '
      || t.table_name || q'[ BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL
     AND INSTR(UPPER(DBMS_UTILITY.FORMAT_CALL_STACK), '.HDR_DEMO') = 0 THEN   -- or the sample of HDR_DEMO
    RAISE_APPLICATION_ERROR(-20690, 'Written by Hader only');
  END IF;
END;]';
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN
    RAISE;
  END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_DEV_REQUESTS_BY BEFORE INSERT ON HADER_DEV_REQUESTS FOR EACH ROW
BEGIN
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100);
  ELSIF :NEW.REQUESTED_BY IS NULL OR SYS_CONTEXT('USERENV', 'SESSION_USER') <> SYS_CONTEXT('USERENV', 'CURRENT_USER') THEN
    :NEW.REQUESTED_BY := SUBSTR(SYS_CONTEXT('USERENV', 'SESSION_USER'), 1, 100);
  END IF;
  IF :NEW.REQ_ID IS NULL THEN
    SELECT HADER_DEV_SEQ.NEXTVAL INTO :NEW.REQ_ID FROM DUAL;
  END IF;
  :NEW.STATUS := 'NEW';
  :NEW.REQUESTED_AT := SYSDATE;
  :NEW.PICKED_AT := NULL;
  :NEW.FINISHED_AT := NULL;
  :NEW.HTTP_CODE := NULL;
  :NEW.MESSAGE := NULL;
  :NEW.REPLY := NULL;
END;]';
  -- from an APEX session the only change is the asker's own waiting request cancelled; never a delete
  EXECUTE IMMEDIATE q'[
CREATE OR REPLACE TRIGGER HADER_DEV_REQUESTS_UPD BEFORE UPDATE OR DELETE ON HADER_DEV_REQUESTS FOR EACH ROW
BEGIN
  -- HDR_DEMO answering a request of the sample terminals (no Hader server) writes as Hader would
  IF SYS_CONTEXT('APEX$SESSION', 'APP_USER') IS NOT NULL
     AND INSTR(UPPER(DBMS_UTILITY.FORMAT_CALL_STACK), '.HDR_DEMO') = 0 THEN
    IF DELETING OR :OLD.STATUS <> 'NEW' OR :NEW.STATUS <> 'CANCELLED'
       OR NVL(:OLD.REQUESTED_BY, '-') <> SUBSTR(SYS_CONTEXT('APEX$SESSION', 'APP_USER'), 1, 100) THEN
      RAISE_APPLICATION_ERROR(-20691, 'Only your own waiting request can be cancelled');
    END IF;
    :NEW.REQ_ID := :OLD.REQ_ID; :NEW.BATCH_ID := :OLD.BATCH_ID; :NEW.CATEGORY := :OLD.CATEGORY;
    :NEW.ACTION := :OLD.ACTION; :NEW.SN := :OLD.SN; :NEW.TARGET_ID := :OLD.TARGET_ID; :NEW.PARAMS := :OLD.PARAMS;
    :NEW.REQUESTED_BY := :OLD.REQUESTED_BY; :NEW.REQUESTED_AT := :OLD.REQUESTED_AT; :NEW.FINISHED_AT := SYSDATE;
    -- nor an answer of its own making: what a cancelled row says comes from Hader only
    :NEW.PICKED_AT := :OLD.PICKED_AT; :NEW.HTTP_CODE := :OLD.HTTP_CODE; :NEW.MESSAGE := :OLD.MESSAGE;
    :NEW.REPLY := :OLD.REPLY;
  END IF;
END;]';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE <> -1031 THEN
    RAISE;
  END IF;
END;
/

-- ---------------------------------------------------------------- hdr_dev_ui.pks
CREATE OR REPLACE PACKAGE HDR_DEV_UI AS
  -- =====================================================================================
  --  The "Hader Terminals" APEX app's one door to the terminals' link tables (hader_devices_link.sql).
  --
  --  It reads only the HADER_DEV_* tables Hader publishes (and HADER_PUNCHES for the punch log) and writes only
  --  HADER_DEV_REQUESTS: one row per command, decision, setting or read, which the Hader server runs through its
  --  own web endpoint as the Hader account of the APEX user's name, and answers in the same row.
  --  It never calls the gateway's packages (the terminals belong to Hader here, not to this database).
  --  Its checks (may, the whitelist) only spare a person a request Hader would refuse: Hader checks every
  --  request again with the permissions of its own account.
  --  Answers are JSON in plain ASCII (\u escapes) whatever the database character set; the device list has the
  --  keys of HDR_UI.devices, so the terminals plug-in draws either.
  --  Errors are raised as ORA-2069x with an Arabic - English message for the page.
  -- =====================================================================================

  c_open_max      CONSTANT PLS_INTEGER := 60;   -- open requests one person may have at a time
  c_stale_seconds CONSTANT PLS_INTEGER := 30;   -- at least this long without a beat: Hader is not there

  -- who asks: the APEX user signed in, else (a script of this schema's own) the name act_as set, else the
  -- database user. act_as is refused inside an APEX session: there the APEX user is the only name.
  FUNCTION me RETURN VARCHAR2;
  PROCEDURE act_as (p_user IN VARCHAR2);

  -- Y / N: the user's Hader account holds the permission (as Hader last published it); 'superuser' for a super
  -- administrator. A permission that changes something is N while Hader cannot be reached.
  FUNCTION may (p_perm IN VARCHAR2) RETURN VARCHAR2;
  -- 'CATEGORY permission' of an action Hader runs, else NULL (generated from the Hader server's own list)
  FUNCTION rule (p_action IN VARCHAR2) RETURN VARCHAR2;

  FUNCTION state (p_key IN VARCHAR2) RETURN VARCHAR2;     -- a fact Hader published (HADER_DEV_STATE)
  FUNCTION beat_age RETURN NUMBER;                        -- seconds since Hader's last round; NULL: never
  FUNCTION reachable RETURN VARCHAR2;                     -- Y / N
  FUNCTION hader_now RETURN DATE;                         -- Hader's clock now (the times it publishes are its own)

  -- one request; returns its number. p_params: a JSON object in ASCII (\u escapes), at most 4000 characters.
  FUNCTION ask (p_action IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_params IN VARCHAR2 DEFAULT NULL,
                p_target IN NUMBER DEFAULT NULL, p_batch IN NUMBER DEFAULT NULL) RETURN NUMBER;
  -- the same request for several terminals ('SN:SN:SN'), one batch; returns the batch number
  FUNCTION ask_many (p_action IN VARCHAR2, p_sns IN VARCHAR2, p_params IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- {"id","status","code","message","action","sn","reply"}: the asker's own request only
  FUNCTION status (p_req IN NUMBER) RETURN CLOB;
  -- {"batch","total","open","done","failed",...,"rows":[{sn,status,code,message}]}
  FUNCTION batch_status (p_batch IN NUMBER) RETURN CLOB;
  PROCEDURE cancel (p_req IN NUMBER);                     -- one's own request, while it still waits

  -- what the pages and the terminals plug-in draw ---------------------------------------------------------
  FUNCTION devices RETURN CLOB;                           -- the keys of HDR_UI.devices, and more
  FUNCTION device (p_sn IN VARCHAR2) RETURN CLOB;         -- one terminal: every published field, its options
  FUNCTION commands (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  FUNCTION traffic (p_sn IN VARCHAR2 DEFAULT NULL, p_limit IN NUMBER DEFAULT 300) RETURN CLOB;
  FUNCTION punches (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 60) RETURN CLOB;   -- today's, on one terminal
  FUNCTION panel (p_sn IN VARCHAR2) RETURN CLOB;          -- the terminal-like panel's values (JSON or null)
  FUNCTION people (p_q IN VARCHAR2 DEFAULT NULL, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;   -- the picker
  -- the program's lists of the devices module, a page at a time: {"total","rows":[...]} with its keys
  FUNCTION oplog (p_sn IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION errlog (p_sn IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION intake (p_sn IN VARCHAR2 DEFAULT NULL, p_rejected IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0,
                   p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  -- the punch log (HADER_PUNCHES): p_from / p_to 'YYYY-MM-DD', p_sn a terminal, p_dept a department name, p_q an
  -- employee number or name
  FUNCTION punch_log (p_from IN VARCHAR2, p_to IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_dept IN VARCHAR2 DEFAULT NULL,
                      p_q IN VARCHAR2 DEFAULT NULL, p_offset IN NUMBER DEFAULT 0, p_limit IN NUMBER DEFAULT 50) RETURN CLOB;
  FUNCTION departments RETURN CLOB;                       -- {"rows":[{"id","name"}]}: the departments of the people
  -- what the native pages of the app show and send (apex/build_terminals_app.py) ------------------------------
  -- one published field of a terminal by its column name in HADER_DEV_TERMINALS (never its comm key)
  FUNCTION field (p_sn IN VARCHAR2, p_col IN VARCHAR2) RETURN VARCHAR2;
  -- one of the terminal's settings as it last reported it (the panel read, else its options); p_keys 'A|B': the
  -- names the terminals answer it under, the first one found wins
  FUNCTION opt (p_sn IN VARCHAR2, p_keys IN VARCHAR2) RETURN VARCHAR2;
  -- the name of p_keys this terminal reports (the first when it reports none): the one a change is written to
  FUNCTION opt_key (p_sn IN VARCHAR2, p_keys IN VARCHAR2) RETURN VARCHAR2;
  -- '"key":value,' for a JSON object, nothing when the value is null. p_kind: S text, N number, B Y/N as a
  -- boolean, L a list of texts from 'a:b:c'
  FUNCTION pair (p_key IN VARCHAR2, p_value IN NVARCHAR2, p_kind IN VARCHAR2 DEFAULT 'S') RETURN VARCHAR2;
  -- the pair of a setting, only when the new value differs from what the terminal reported
  FUNCTION change (p_sn IN VARCHAR2, p_keys IN VARCHAR2, p_value IN NVARCHAR2) RETURN VARCHAR2;
  -- '{pairs}', or '{"wrap":{pairs}}'; NULL when there is no pair and no wrap (nothing to send)
  FUNCTION obj (p_pairs IN VARCHAR2, p_wrap IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION first_sn (p_sns IN VARCHAR2) RETURN VARCHAR2;  -- the first of 'SN:SN:SN', refused when none
  -- the terminals ticked in the device list ('SN:SN:SN'): the boxes of its rows (APEX's f01 of the page just
  -- submitted); NULL outside APEX or when none is ticked
  FUNCTION picked RETURN VARCHAR2;
  -- the line a page shows for one of the asker's requests or batches: status and Hader's message
  FUNCTION said (p_req IN NUMBER) RETURN VARCHAR2;
  FUNCTION said_batch (p_batch IN NUMBER) RETURN VARCHAR2;
  -- the answer of one of the asker's READ requests (its first 4000 characters)
  FUNCTION reply_text (p_req IN NUMBER) RETURN VARCHAR2;
END HDR_DEV_UI;
/

-- ---------------------------------------------------------------- hdr_schema.sql
DECLARE
  n NUMBER;
  PROCEDURE ddl (p_name IN VARCHAR2, p_sql IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name;
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_sql;
    END IF;
  END;
  PROCEDURE col (p_table IN VARCHAR2, p_col IN VARCHAR2, p_def IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = p_table AND column_name = p_col;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_col || ' ' || p_def || ')';
    END IF;
  END;
BEGIN
  ddl('HDR_SEQ', 'CREATE SEQUENCE HDR_SEQ CACHE 100');

  -- ---------------------------------------------------------------- settings
  ddl('HDR_SETTINGS', q'[
    CREATE TABLE HDR_SETTINGS (
      SKEY   VARCHAR2(60) NOT NULL,
      SVALUE VARCHAR2(4000),
      CONSTRAINT HDR_SETTINGS_PK PRIMARY KEY (SKEY))]');

  -- the English of APEX app 141's own words (2.3.6): its pages, items and buttons are written in Arabic and their
  -- English is a translation of them (HDR_UI.publish_english); filled by hdr_i18n.sql from apex/i18n/ar_en.json
  ddl('HDR_I18N', q'[
    CREATE TABLE HDR_I18N (
      AR NVARCHAR2(1000) NOT NULL,
      EN VARCHAR2(2000)  NOT NULL,
      CONSTRAINT HDR_I18N_PK PRIMARY KEY (AR))]');

  -- ---------------------------------------------------------------- people
  ddl('HDR_AREAS', q'[
    CREATE TABLE HDR_AREAS (
      AREA_ID    NUMBER        NOT NULL,
      AREA_CODE  VARCHAR2(50)  NOT NULL,
      NAME       NVARCHAR2(120) NOT NULL,
      NAME_EN    VARCHAR2(120),
      CONSTRAINT HDR_AREAS_PK PRIMARY KEY (AREA_ID),
      CONSTRAINT HDR_AREAS_UK UNIQUE (AREA_CODE))]');

  ddl('HDR_DEPARTMENTS', q'[
    CREATE TABLE HDR_DEPARTMENTS (
      DEPT_CODE   VARCHAR2(50)   NOT NULL,
      NAME        NVARCHAR2(120) NOT NULL,
      NAME_EN     VARCHAR2(120),
      PARENT_CODE VARCHAR2(50),
      CONSTRAINT HDR_DEPARTMENTS_PK PRIMARY KEY (DEPT_CODE))]');

  ddl('HDR_EMPLOYEES', q'[
    CREATE TABLE HDR_EMPLOYEES (
      EMP_ID        NUMBER         NOT NULL,
      EMP_CODE      VARCHAR2(30)   NOT NULL,          -- the number used on the terminals (PIN)
      FULL_NAME     NVARCHAR2(200),
      NAME_EN       VARCHAR2(160),
      DEPT_CODE     VARCHAR2(50),
      POSITION_NAME NVARCHAR2(120),
      HIRE_DATE     DATE,
      STATUS        VARCHAR2(10)   DEFAULT 'active' NOT NULL,   -- active / resigned
      RESIGN_DATE   DATE,
      CARD_NO       VARCHAR2(30),
      DEV_PASSWORD  VARCHAR2(30),
      DEV_PRIVILEGE NUMBER(3)      DEFAULT 0 NOT NULL,          -- 0 user, 14 terminal administrator
      VERIFY_MODE   NUMBER(3)      DEFAULT -1 NOT NULL,         -- -1 = terminal default
      ENABLE_ATT    CHAR(1)        DEFAULT 'Y' NOT NULL,
      EMAIL         VARCHAR2(120),
      MOBILE        VARCHAR2(50),
      SOURCE        VARCHAR2(10)   DEFAULT 'LOCAL' NOT NULL,    -- HR / LOCAL / DEVICE
      CREATED_AT    DATE           DEFAULT SYSDATE NOT NULL,
      UPDATED_AT    DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_EMPLOYEES_PK PRIMARY KEY (EMP_ID),
      CONSTRAINT HDR_EMPLOYEES_UK UNIQUE (EMP_CODE))]');
  ddl('HDR_EMPLOYEES_DEPT_IX', 'CREATE INDEX HDR_EMPLOYEES_DEPT_IX ON HDR_EMPLOYEES (DEPT_CODE, STATUS)');

  ddl('HDR_EMP_AREAS', q'[
    CREATE TABLE HDR_EMP_AREAS (
      EMP_CODE VARCHAR2(30) NOT NULL,
      AREA_ID  NUMBER       NOT NULL,
      CONSTRAINT HDR_EMP_AREAS_PK PRIMARY KEY (EMP_CODE, AREA_ID))]');
  ddl('HDR_EMP_AREAS_AREA_IX', 'CREATE INDEX HDR_EMP_AREAS_AREA_IX ON HDR_EMP_AREAS (AREA_ID)');

  -- BIODATA types: 1 fingerprint, 2 near-infrared face, 7 finger vein, 8 palm, 9 visible-light face
  ddl('HDR_BIO', q'[
    CREATE TABLE HDR_BIO (
      BIO_ID     NUMBER        NOT NULL,
      EMP_CODE   VARCHAR2(30)  NOT NULL,
      BIO_TYPE   NUMBER(3)     NOT NULL,
      BIO_NO     NUMBER(3)     DEFAULT 0 NOT NULL,
      BIO_INDEX  NUMBER(3)     DEFAULT 0 NOT NULL,
      VALID      NUMBER(3)     DEFAULT 1 NOT NULL,
      DURESS     NUMBER(3)     DEFAULT 0 NOT NULL,
      MAJOR_VER  VARCHAR2(10)  DEFAULT '0' NOT NULL,     -- algorithm version; 0 = not known
      MINOR_VER  VARCHAR2(10),
      BIO_FORMAT NUMBER(3)     DEFAULT 0 NOT NULL,
      TEMPLATE   CLOB          NOT NULL,                 -- base64, as the terminal sends it
      SOURCE_SN  VARCHAR2(50),
      UPDATED_AT DATE          DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_BIO_PK PRIMARY KEY (BIO_ID),
      CONSTRAINT HDR_BIO_UK UNIQUE (EMP_CODE, BIO_TYPE, BIO_NO, BIO_INDEX, MAJOR_VER))]');

  ddl('HDR_BIO_PHOTOS', q'[
    CREATE TABLE HDR_BIO_PHOTOS (
      EMP_CODE   VARCHAR2(30) NOT NULL,
      BIO_TYPE   NUMBER(3)    DEFAULT 9 NOT NULL,       -- enrollment photo a terminal can re-extract
      CONTENT    CLOB         NOT NULL,                 -- base64 JPEG
      SOURCE_SN  VARCHAR2(50),
      UPDATED_AT DATE         DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_BIO_PHOTOS_PK PRIMARY KEY (EMP_CODE, BIO_TYPE))]');

  -- ---------------------------------------------------------------- terminals
  ddl('HDR_DEVICES', q'[
    CREATE TABLE HDR_DEVICES (
      DEVICE_ID      NUMBER         NOT NULL,
      SN             VARCHAR2(50)   NOT NULL,
      ALIAS          NVARCHAR2(100),
      ALIAS_EN       VARCHAR2(100),
      AREA_ID        NUMBER,
      IP             VARCHAR2(50),
      ENABLED        CHAR(1)        DEFAULT 'Y' NOT NULL,
      IS_ATTENDANCE  CHAR(1)        DEFAULT 'Y' NOT NULL,     -- its punches count for attendance
      TIME_ZONE      NUMBER(3),                               -- hours; empty = the setting
      HEARTBEAT      NUMBER(4)      DEFAULT 10 NOT NULL,      -- seconds between requests
      TRANS_INTERVAL NUMBER(4)      DEFAULT 1 NOT NULL,
      TRANS_TIMES    VARCHAR2(100)  DEFAULT '00:00;14:05' NOT NULL,
      REALTIME       CHAR(1)        DEFAULT 'Y' NOT NULL,
      ALLOWED_IPS    VARCHAR2(400),                           -- optional: addresses it may send from
      MODEL          VARCHAR2(100),
      FIRMWARE       VARCHAR2(100),
      PUSH_VER       VARCHAR2(30),
      PLATFORM       VARCHAR2(60),
      MAC            VARCHAR2(30),
      FP_ALG         VARCHAR2(20),
      FACE_ALG       VARCHAR2(20),
      USER_COUNT     NUMBER         DEFAULT 0 NOT NULL,
      FP_COUNT       NUMBER         DEFAULT 0 NOT NULL,
      FACE_COUNT     NUMBER         DEFAULT 0 NOT NULL,
      PALM_COUNT     NUMBER         DEFAULT 0 NOT NULL,
      ATT_COUNT      NUMBER         DEFAULT 0 NOT NULL,
      OPTIONS        CLOB,                                    -- Key=Value lines reported by the terminal
      ATT_STAMP      VARCHAR2(30)   DEFAULT '0' NOT NULL,
      OP_STAMP       VARCHAR2(30)   DEFAULT '0' NOT NULL,
      PHOTO_STAMP    VARCHAR2(30)   DEFAULT '0' NOT NULL,
      TODAY_STATE    VARCHAR2(400),                           -- request for today's punches kept on the terminal
      LAST_ACTIVITY  DATE,
      LAST_INIT      DATE,
      LAST_SYNC      DATE,
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_DEVICES_PK PRIMARY KEY (DEVICE_ID),
      CONSTRAINT HDR_DEVICES_UK UNIQUE (SN))]');

  ddl('HDR_COMMANDS', q'[
    CREATE TABLE HDR_COMMANDS (
      CMD_ID       NUMBER         NOT NULL,                  -- the C:<id>: of the protocol
      SN           VARCHAR2(50)   NOT NULL,
      CONTENT      NCLOB          NOT NULL,                  -- Unicode: names travel inside user commands
      CONTENT_KEY  VARCHAR2(40)   NOT NULL,                  -- length + hash, for de-duplication
      TITLE        NVARCHAR2(120),
      STATUS       VARCHAR2(10)   DEFAULT 'pending' NOT NULL,  -- pending / sent / done / failed
      ATTEMPTS     NUMBER(3)      DEFAULT 0 NOT NULL,
      RETURN_CODE  VARCHAR2(20),
      RESULT       VARCHAR2(4000),
      CREATED_BY   VARCHAR2(100),
      CREATED_AT   DATE           DEFAULT SYSDATE NOT NULL,
      SENT_AT      DATE,
      RETURNED_AT  DATE,
      CONSTRAINT HDR_COMMANDS_PK PRIMARY KEY (CMD_ID))]');
  ddl('HDR_COMMANDS_SN_IX', 'CREATE INDEX HDR_COMMANDS_SN_IX ON HDR_COMMANDS (SN, STATUS, CMD_ID)');
  ddl('HDR_COMMANDS_KEY_IX', 'CREATE INDEX HDR_COMMANDS_KEY_IX ON HDR_COMMANDS (SN, CONTENT_KEY)');
  -- the checks of the last minutes or the last day (heartbeat, punch, clock, arrows that turn): a range of the
  -- terminal's newest commands, not the month of history it keeps
  ddl('HDR_COMMANDS_AT_IX', 'CREATE INDEX HDR_COMMANDS_AT_IX ON HDR_COMMANDS (SN, CREATED_AT)');
  ddl('HDR_COMMANDS_SENT_IX', 'CREATE INDEX HDR_COMMANDS_SENT_IX ON HDR_COMMANDS (SN, SENT_AT)');

  ddl('HDR_OPLOG', q'[
    CREATE TABLE HDR_OPLOG (
      LOG_ID      NUMBER       NOT NULL,
      SN          VARCHAR2(50) NOT NULL,
      OP_CODE     NUMBER(5),
      ADMIN       VARCHAR2(30),
      OP_TIME     DATE,
      OBJ1        VARCHAR2(50), OBJ2 VARCHAR2(50), OBJ3 VARCHAR2(50), OBJ4 VARCHAR2(50),
      UPLOAD_TIME DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_OPLOG_PK PRIMARY KEY (LOG_ID))]');

  -- a terminal back after a silence (power or network cut), on its own clock (as HADER_PUNCHES): the punches it
  -- kept before its clock was set again are looked for from here (HDR_V_RETURN_PUNCHES, HDR_UI.clock_fix)
  ddl('HDR_RETURNS', q'[
    CREATE TABLE HDR_RETURNS (
      RETURN_ID      NUMBER        NOT NULL,
      SN             VARCHAR2(50)  NOT NULL,
      RETURNED_AT    DATE          NOT NULL,
      LAST_SEEN      DATE          NOT NULL,
      STATUS         VARCHAR2(10)  DEFAULT 'open' NOT NULL,
      OFFSET_SECONDS NUMBER(9),
      FIXED_COUNT    NUMBER(9),
      FIXED_BY       VARCHAR2(100),
      FIXED_AT       DATE,
      CLOCK_AT       DATE,
      CONSTRAINT HDR_RETURNS_PK PRIMARY KEY (RETURN_ID))]');
  col('HDR_RETURNS', 'CLOCK_AT', 'DATE');      -- its clock set on this return (the bell says so once, HDR_ALERTS)
  ddl('HDR_RETURNS_IX', 'CREATE INDEX HDR_RETURNS_IX ON HDR_RETURNS (STATUS, RETURNED_AT)');

  ddl('HDR_ERRLOG', q'[
    CREATE TABLE HDR_ERRLOG (
      LOG_ID      NUMBER       NOT NULL,
      SN          VARCHAR2(50) NOT NULL,
      ERR_CODE    VARCHAR2(20),
      ERR_MSG     VARCHAR2(2000),
      DATA        VARCHAR2(2000),
      UPLOAD_TIME DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_ERRLOG_PK PRIMARY KEY (LOG_ID))]');

  -- every request of the terminals (communication monitor; kept a few days)
  ddl('HDR_TRAFFIC', q'[
    CREATE TABLE HDR_TRAFFIC (
      LOG_ID  NUMBER        NOT NULL,
      LOGGED_AT TIMESTAMP   DEFAULT SYSTIMESTAMP NOT NULL,
      SN      VARCHAR2(50),
      IP      VARCHAR2(50),
      METHOD  VARCHAR2(10),
      PATH    VARCHAR2(100),
      QUERY   VARCHAR2(400),
      BYTES   NUMBER,
      STATUS  NUMBER(3),
      REPLY   VARCHAR2(400),
      CONSTRAINT HDR_TRAFFIC_PK PRIMARY KEY (LOG_ID))]');
  ddl('HDR_TRAFFIC_AT_IX', 'CREATE INDEX HDR_TRAFFIC_AT_IX ON HDR_TRAFFIC (SN, LOGGED_AT)');

  -- punch lines a terminal sent that could not be stored (the inbox)
  -- 2.3.6: what a terminal sent that would change a person kept here (a card, a password, a higher privilege),
  -- held until a person decides (HDR_UI device_do held_accept / held_reject): a terminal is known by its serial
  -- number and address only, so it never raises a privilege nor replaces a card or a password by itself
  ddl('HDR_HELD', q'[
    CREATE TABLE HDR_HELD (
      HELD_ID    NUMBER        NOT NULL,
      SN         VARCHAR2(50)  NOT NULL,
      EMP_CODE   VARCHAR2(30)  NOT NULL,
      FIELD      VARCHAR2(20)  NOT NULL,                   -- card / password / privilege
      VALUE      VARCHAR2(60),
      HELD_AT    DATE          DEFAULT SYSDATE NOT NULL,
      DECISION   VARCHAR2(10),                             -- NULL: waiting; accepted / rejected
      DECIDED_BY VARCHAR2(255),
      DECIDED_AT DATE,
      CONSTRAINT HDR_HELD_PK PRIMARY KEY (HELD_ID))]');
  ddl('HDR_HELD_W_IX', 'CREATE INDEX HDR_HELD_W_IX ON HDR_HELD (DECISION, SN)');

  ddl('HDR_REJECTS', q'[
    CREATE TABLE HDR_REJECTS (
      LOG_ID  NUMBER        NOT NULL,
      LOGGED_AT DATE        DEFAULT SYSDATE NOT NULL,
      SN      VARCHAR2(50),
      LINE_NO NUMBER,
      REASON  VARCHAR2(40),
      LINE    VARCHAR2(1000),
      CONSTRAINT HDR_REJECTS_PK PRIMARY KEY (LOG_ID))]');

  -- employee-days whose attendance must be calculated again (new punches, leave, schedule changes)
  ddl('HDR_DIRTY', q'[
    CREATE TABLE HDR_DIRTY (
      EMP_CODE VARCHAR2(30) NOT NULL,
      ATT_DATE DATE         NOT NULL,
      MARKED_AT DATE        DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_DIRTY_PK PRIMARY KEY (EMP_CODE, ATT_DATE))]');

  -- ---------------------------------------------------------------- attendance rules
  -- times are 'HH24:MI'; minutes are whole minutes
  ddl('HDR_TIMETABLES', q'[
    CREATE TABLE HDR_TIMETABLES (
      TT_ID        NUMBER         NOT NULL,
      ALIAS        NVARCHAR2(60)  NOT NULL,
      KIND         VARCHAR2(10)   DEFAULT 'normal' NOT NULL,   -- normal / flexible
      CHECK_IN     VARCHAR2(5)    DEFAULT '08:00' NOT NULL,
      CHECK_OUT    VARCHAR2(5)    DEFAULT '16:00' NOT NULL,
      IN_AHEAD     NUMBER(5)      DEFAULT 120 NOT NULL,        -- check-in accepted from .. minutes before
      IN_ABOVE     NUMBER(5)      DEFAULT 240 NOT NULL,        -- .. until .. minutes after
      OUT_AHEAD    NUMBER(5)      DEFAULT 240 NOT NULL,
      OUT_ABOVE    NUMBER(5)      DEFAULT 240 NOT NULL,
      LATE_GRACE   NUMBER(5)      DEFAULT 0 NOT NULL,
      EARLY_GRACE  NUMBER(5)      DEFAULT 0 NOT NULL,
      MUST_IN      CHAR(1)        DEFAULT 'Y' NOT NULL,
      MUST_OUT     CHAR(1)        DEFAULT 'Y' NOT NULL,
      BREAK_START  VARCHAR2(5),
      BREAK_END    VARCHAR2(5),
      WORK_MINUTES NUMBER(5)      DEFAULT 480 NOT NULL,        -- flexible: minutes required in the day
      WORKDAY      NUMBER(4,2)    DEFAULT 1 NOT NULL,          -- counts as .. work days
      COLOR        VARCHAR2(10)   DEFAULT '#1e88e5',
      CONSTRAINT HDR_TIMETABLES_PK PRIMARY KEY (TT_ID),
      CONSTRAINT HDR_TIMETABLES_UK UNIQUE (ALIAS))]');

  ddl('HDR_SHIFTS', q'[
    CREATE TABLE HDR_SHIFTS (
      SHIFT_ID   NUMBER         NOT NULL,
      ALIAS      NVARCHAR2(60)  NOT NULL,
      CYCLE_UNIT VARCHAR2(5)    DEFAULT 'week' NOT NULL,     -- day / week / month
      CYCLE      NUMBER(3)      DEFAULT 1 NOT NULL,
      CONSTRAINT HDR_SHIFTS_PK PRIMARY KEY (SHIFT_ID),
      CONSTRAINT HDR_SHIFTS_UK UNIQUE (ALIAS))]');

  -- week cycles: DAY_INDEX 0 = Monday .. 6 = Sunday (+7 per further week); month: 0..30 (+31 per month)
  ddl('HDR_SHIFT_DAYS', q'[
    CREATE TABLE HDR_SHIFT_DAYS (
      SHIFT_ID  NUMBER    NOT NULL,
      DAY_INDEX NUMBER(4) NOT NULL,
      TT_ID     NUMBER    NOT NULL,
      CONSTRAINT HDR_SHIFT_DAYS_PK PRIMARY KEY (SHIFT_ID, DAY_INDEX, TT_ID))]');

  ddl('HDR_SCHEDULES', q'[
    CREATE TABLE HDR_SCHEDULES (
      SCHED_ID     NUMBER       NOT NULL,
      EMP_CODE     VARCHAR2(30) NOT NULL,
      SHIFT_ID     NUMBER       NOT NULL,
      START_DATE   DATE         NOT NULL,
      END_DATE     DATE         NOT NULL,
      CYCLE_ANCHOR DATE,                                   -- keeps the cycle when a range is split
      CONSTRAINT HDR_SCHEDULES_PK PRIMARY KEY (SCHED_ID))]');
  ddl('HDR_SCHEDULES_EMP_IX', 'CREATE INDEX HDR_SCHEDULES_EMP_IX ON HDR_SCHEDULES (EMP_CODE, START_DATE, END_DATE)');

  ddl('HDR_DEPT_SCHEDULES', q'[
    CREATE TABLE HDR_DEPT_SCHEDULES (
      SCHED_ID     NUMBER       NOT NULL,
      DEPT_CODE    VARCHAR2(50) NOT NULL,
      SHIFT_ID     NUMBER       NOT NULL,
      START_DATE   DATE         NOT NULL,
      END_DATE     DATE         NOT NULL,
      CYCLE_ANCHOR DATE,                                   -- keeps the cycle when a range is split
      CONSTRAINT HDR_DEPT_SCHEDULES_PK PRIMARY KEY (SCHED_ID))]');
  col('HDR_DEPT_SCHEDULES', 'CYCLE_ANCHOR', 'DATE');
  -- each employee's department schedules (the engine reads them per employee)
  ddl('HDR_DEPT_SCHEDULES_IX', 'CREATE INDEX HDR_DEPT_SCHEDULES_IX ON HDR_DEPT_SCHEDULES (DEPT_CODE, START_DATE, END_DATE)');

  -- one-day override: TT_ID empty = day off
  ddl('HDR_TEMP_SCHEDULES', q'[
    CREATE TABLE HDR_TEMP_SCHEDULES (
      TEMP_ID  NUMBER       NOT NULL,
      EMP_CODE VARCHAR2(30) NOT NULL,
      ATT_DATE DATE         NOT NULL,
      TT_ID    NUMBER,
      CONSTRAINT HDR_TEMP_SCHEDULES_PK PRIMARY KEY (TEMP_ID))]');
  ddl('HDR_TEMP_SCHEDULES_IX', 'CREATE INDEX HDR_TEMP_SCHEDULES_IX ON HDR_TEMP_SCHEDULES (EMP_CODE, ATT_DATE)');

  ddl('HDR_HOLIDAYS', q'[
    CREATE TABLE HDR_HOLIDAYS (
      HOLIDAY_ID NUMBER         NOT NULL,
      ALIAS      NVARCHAR2(80)  NOT NULL,
      START_DATE DATE           NOT NULL,
      DAYS       NUMBER(3)      DEFAULT 1 NOT NULL,
      DEPT_CODE  VARCHAR2(50),                             -- empty = everyone
      CONSTRAINT HDR_HOLIDAYS_PK PRIMARY KEY (HOLIDAY_ID))]');

  ddl('HDR_LEAVE_TYPES', q'[
    CREATE TABLE HDR_LEAVE_TYPES (
      LEAVE_CODE  VARCHAR2(10)  NOT NULL,
      NAME        NVARCHAR2(60) NOT NULL,
      NAME_EN     VARCHAR2(120),
      PAID        CHAR(1)       DEFAULT 'Y' NOT NULL,
      COLOR       VARCHAR2(10)  DEFAULT '#8e24aa',
      ANNUAL_DAYS NUMBER(4)     DEFAULT 0 NOT NULL,
      CONSTRAINT HDR_LEAVE_TYPES_PK PRIMARY KEY (LEAVE_CODE))]');

  ddl('HDR_LEAVES', q'[
    CREATE TABLE HDR_LEAVES (
      LEAVE_ID   NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      LEAVE_CODE VARCHAR2(10)   NOT NULL,
      START_TIME DATE           NOT NULL,                  -- whole days: 00:00 of the first day
      END_TIME   DATE           NOT NULL,                  -- whole days: 00:00 of the day after the last
      REASON     NVARCHAR2(250),
      STATUS     VARCHAR2(10)   DEFAULT 'approved' NOT NULL,   -- pending / approved / rejected
      APPROVER   VARCHAR2(100),
      SOURCE     VARCHAR2(10)   DEFAULT 'admin' NOT NULL,      -- admin / hr
      EXT_REF    VARCHAR2(70),                             -- id in the HR system
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_LEAVES_PK PRIMARY KEY (LEAVE_ID))]');
  ddl('HDR_LEAVES_EMP_IX', 'CREATE INDEX HDR_LEAVES_EMP_IX ON HDR_LEAVES (EMP_CODE, START_TIME)');
  ddl('HDR_LEAVES_REF_IX', 'CREATE INDEX HDR_LEAVES_REF_IX ON HDR_LEAVES (EXT_REF)');
  -- the requests waiting (counts on the dashboard, alerts every minute): a few index blocks, not every row
  ddl('HDR_LEAVES_ST_IX', 'CREATE INDEX HDR_LEAVES_ST_IX ON HDR_LEAVES (STATUS, CREATED_AT)');

  -- forgotten punches entered by hand, counted once approved
  ddl('HDR_MANUAL_PUNCHES', q'[
    CREATE TABLE HDR_MANUAL_PUNCHES (
      MANUAL_ID   NUMBER         NOT NULL,
      EMP_CODE    VARCHAR2(30)   NOT NULL,
      PUNCH_TIME  DATE           NOT NULL,
      PUNCH_STATE NUMBER(3)      DEFAULT 0 NOT NULL,
      REASON      NVARCHAR2(250),
      STATUS      VARCHAR2(10)   DEFAULT 'approved' NOT NULL,
      APPROVER    VARCHAR2(100),
      CREATED_AT  DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_MANUAL_PUNCHES_PK PRIMARY KEY (MANUAL_ID))]');
  ddl('HDR_MANUAL_PUNCHES_IX', 'CREATE INDEX HDR_MANUAL_PUNCHES_IX ON HDR_MANUAL_PUNCHES (EMP_CODE, PUNCH_TIME)');
  ddl('HDR_MANUAL_PUNCHES_ST_IX', 'CREATE INDEX HDR_MANUAL_PUNCHES_ST_IX ON HDR_MANUAL_PUNCHES (STATUS, CREATED_AT)');

  ddl('HDR_OVERTIME', q'[
    CREATE TABLE HDR_OVERTIME (
      OT_ID      NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      START_TIME DATE           NOT NULL,
      END_TIME   DATE           NOT NULL,
      REASON     NVARCHAR2(250),
      STATUS     VARCHAR2(10)   DEFAULT 'approved' NOT NULL,
      APPROVER   VARCHAR2(100),
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_OVERTIME_PK PRIMARY KEY (OT_ID))]');
  ddl('HDR_OVERTIME_IX', 'CREATE INDEX HDR_OVERTIME_IX ON HDR_OVERTIME (EMP_CODE, START_TIME)');
  ddl('HDR_OVERTIME_ST_IX', 'CREATE INDEX HDR_OVERTIME_ST_IX ON HDR_OVERTIME (STATUS, CREATED_AT)');

  -- dated versions (HDR_POLICY): an edit of a timetable, of a shift (its cycle and days) or of the attendance
  -- rules never changes the days before it. Each row is the whole version in force from EFFECTIVE_FROM, rebuilt
  -- from the edits whenever one is added (the program's attendance_policy, hader/policy_history.py):
  --   VER_KIND baseline  what applied before the first edit, from the beginning of time (0001-01-01)
  --            edit      CHANGED: the columns (rules: the keys) this edit set itself
  --            return    the day after a period's last day: what that period set comes back (CLOSES: its edit)
  -- Without a row the timetable / shift / rule itself (HDR_TIMETABLES, HDR_SHIFTS, HDR_SETTINGS) applies.
  ddl('HDR_TIMETABLE_VERSIONS', q'[
    CREATE TABLE HDR_TIMETABLE_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      TT_ID          NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),
      ALIAS          NVARCHAR2(60),
      KIND           VARCHAR2(10),
      CHECK_IN       VARCHAR2(5),
      CHECK_OUT      VARCHAR2(5),
      IN_AHEAD       NUMBER(5),
      IN_ABOVE       NUMBER(5),
      OUT_AHEAD      NUMBER(5),
      OUT_ABOVE      NUMBER(5),
      LATE_GRACE     NUMBER(5),
      EARLY_GRACE    NUMBER(5),
      MUST_IN        CHAR(1),
      MUST_OUT       CHAR(1),
      BREAK_START    VARCHAR2(5),
      BREAK_END      VARCHAR2(5),
      WORK_MINUTES   NUMBER(5),
      WORKDAY        NUMBER(4,2),
      COLOR          VARCHAR2(10),
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_TIMETABLE_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  ddl('HDR_TIMETABLE_VERSIONS_IX', 'CREATE INDEX HDR_TIMETABLE_VERSIONS_IX ON HDR_TIMETABLE_VERSIONS (TT_ID, EFFECTIVE_FROM)');

  ddl('HDR_SHIFT_VERSIONS', q'[
    CREATE TABLE HDR_SHIFT_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      SHIFT_ID       NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),                       -- CYCLE_UNIT, CYCLE, DAYS
      CYCLE_UNIT     VARCHAR2(5),
      CYCLE          NUMBER(3),
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_SHIFT_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  ddl('HDR_SHIFT_VERSIONS_IX', 'CREATE INDEX HDR_SHIFT_VERSIONS_IX ON HDR_SHIFT_VERSIONS (SHIFT_ID, EFFECTIVE_FROM)');
  -- the days of a shift's version, as HDR_SHIFT_DAYS holds them for the shift itself
  ddl('HDR_SHIFT_VERSION_DAYS', q'[
    CREATE TABLE HDR_SHIFT_VERSION_DAYS (
      VER_ID    NUMBER    NOT NULL,
      DAY_INDEX NUMBER(4) NOT NULL,
      TT_ID     NUMBER    NOT NULL,
      CONSTRAINT HDR_SHIFT_VERSION_DAYS_PK PRIMARY KEY (VER_ID, DAY_INDEX, TT_ID))]');
  ddl('HDR_SHIFT_VERSION_DAYS_TT_IX', 'CREATE INDEX HDR_SHIFT_VERSION_DAYS_TT_IX ON HDR_SHIFT_VERSION_DAYS (TT_ID)');

  ddl('HDR_RULE_VERSIONS', q'[
    CREATE TABLE HDR_RULE_VERSIONS (
      VER_ID         NUMBER         NOT NULL,
      EFFECTIVE_FROM DATE           NOT NULL,
      VER_KIND       VARCHAR2(10)   DEFAULT 'edit' NOT NULL,
      CLOSES         NUMBER,
      CHANGED        VARCHAR2(1000),                       -- the att.* keys
      REASON         NVARCHAR2(300),
      ACTOR          VARCHAR2(255),
      CREATED_AT     DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_RULE_VERSIONS_PK PRIMARY KEY (VER_ID))]');
  -- the rules of a version, as HDR_SETTINGS holds them (att.* keys and values)
  ddl('HDR_RULE_VERSION_VALUES', q'[
    CREATE TABLE HDR_RULE_VERSION_VALUES (
      VER_ID NUMBER         NOT NULL,
      SKEY   VARCHAR2(60)   NOT NULL,
      SVALUE VARCHAR2(4000),
      CONSTRAINT HDR_RULE_VERSION_VALUES_PK PRIMARY KEY (VER_ID, SKEY))]');

  -- the accounts of the Hader program as APEX app 141 knows them (an APEX user is the account of the same name):
  -- the permissions of its role (PERMISSIONS: attendance.approve, attendance.approve_all - the general manager -,
  -- system.admin ...), the employee it is (EMP_CODE: their own requests are never theirs to decide). SOURCE HADER:
  -- kept by the Hader server; APEX: added in the app. With no account at all, every APEX user decides as before.
  ddl('HDR_USERS', q'[
    CREATE TABLE HDR_USERS (
      USERNAME    VARCHAR2(255)  NOT NULL,
      FULL_NAME   NVARCHAR2(100),
      EMP_CODE    VARCHAR2(30),
      PERMISSIONS VARCHAR2(1000),
      ACTIVE      CHAR(1)        DEFAULT 'Y' NOT NULL,
      SOURCE      VARCHAR2(10)   DEFAULT 'APEX' NOT NULL,
      UPDATED_AT  DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_USERS_PK PRIMARY KEY (USERNAME))]');

  -- who decides a department's requests (leave, manual punches, overtime) and those of the departments under it:
  -- its head, and deputies standing in for the head, each for a period (both days counted) or always (no dates).
  -- The program's department_approver (hader/approvals.py); deciding still needs attendance.approve.
  ddl('HDR_APPROVERS', q'[
    CREATE TABLE HDR_APPROVERS (
      APPROVER_ID NUMBER        NOT NULL,
      DEPT_CODE   VARCHAR2(50)  NOT NULL,
      USERNAME    VARCHAR2(255) NOT NULL,
      KIND        VARCHAR2(10)  DEFAULT 'head' NOT NULL,     -- head / deputy
      START_DATE  DATE,
      END_DATE    DATE,
      CONSTRAINT HDR_APPROVERS_PK PRIMARY KEY (APPROVER_ID))]');
  ddl('HDR_APPROVERS_DEPT_IX', 'CREATE INDEX HDR_APPROVERS_DEPT_IX ON HDR_APPROVERS (DEPT_CODE)');
  ddl('HDR_APPROVERS_USER_IX', 'CREATE INDEX HDR_APPROVERS_USER_IX ON HDR_APPROVERS (USERNAME)');

  -- the bell of APEX app 141: the program's alerts (hader/alerts.py), each event told once (HDR_ALERTS)
  ddl('HDR_NOTIFICATIONS', q'[
    CREATE TABLE HDR_NOTIFICATIONS (
      NOTE_ID    NUMBER         NOT NULL,
      AKEY       VARCHAR2(160)  NOT NULL,                  -- the event, as the program's alert log keys it
      KIND       VARCHAR2(20)   NOT NULL,                  -- late / absent / missing_out / device_offline / ...
      LVL        VARCHAR2(10)   DEFAULT 'info' NOT NULL,   -- good / info / warn / bad
      TITLE      NVARCHAR2(200),
      BODY       NVARCHAR2(1000),
      PAGE_ID    NUMBER(6),                                -- the page of APEX app 141 it opens
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_NOTIFICATIONS_PK PRIMARY KEY (NOTE_ID),
      CONSTRAINT HDR_NOTIFICATIONS_UK UNIQUE (AKEY))]');
  ddl('HDR_NOTIFICATIONS_AT_IX', 'CREATE INDEX HDR_NOTIFICATIONS_AT_IX ON HDR_NOTIFICATIONS (CREATED_AT)');
  -- who has read which (an APEX user)
  ddl('HDR_NOTIFICATION_READS', q'[
    CREATE TABLE HDR_NOTIFICATION_READS (
      NOTE_ID  NUMBER         NOT NULL,
      USERNAME VARCHAR2(255)  NOT NULL,
      READ_AT  DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_NOTIFICATION_READS_PK PRIMARY KEY (NOTE_ID, USERNAME))]');

  -- the Hader assistant in APEX app 141: a question, or a decision on a proposal, waits here; the Hader server, connected
  -- to this schema, takes it within seconds and writes the answer as it grows (hader/ai/apex.py, HDR_UI.ai_*)
  ddl('HDR_AI_CHAT', q'[
    CREATE TABLE HDR_AI_CHAT (
      REQ_ID     NUMBER         NOT NULL,
      KIND       VARCHAR2(10)   DEFAULT 'ASK' NOT NULL,   -- ASK / RUN / DECLINE (a proposal) / DROP (a conversation)
      APEX_USER  VARCHAR2(255)  NOT NULL,
      CONV_ID    NUMBER,                                   -- the conversation, as the Hader server numbers it
      REF_ID     NUMBER,                                   -- RUN / DECLINE: the question whose answer proposed it
      ACTION_ID  NUMBER,                                   -- RUN / DECLINE: the proposal
      QUESTION   CLOB,
      STATUS     VARCHAR2(10)   DEFAULT 'NEW' NOT NULL,   -- NEW / RUNNING / STOP (asked to stop) / DONE / FAILED
      REPLY      CLOB,                                     -- the answer for the page: JSON in plain ASCII
      ASKED_AT   DATE           DEFAULT SYSDATE NOT NULL,
      UPDATED_AT DATE,
      CONSTRAINT HDR_AI_CHAT_PK PRIMARY KEY (REQ_ID))]');
  ddl('HDR_AI_CHAT_ST_IX', 'CREATE INDEX HDR_AI_CHAT_ST_IX ON HDR_AI_CHAT (STATUS)');
  ddl('HDR_AI_CHAT_U_IX', 'CREATE INDEX HDR_AI_CHAT_U_IX ON HDR_AI_CHAT (APEX_USER, CONV_ID)');
  -- a file the assistant made for an APEX user (an Excel sheet, a ZIP of pictures): copied here by the Hader server
  -- with the answer, so the page downloads it (HDR_UI.ai_file); it goes with its conversation
  ddl('HDR_AI_FILES', q'[
    CREATE TABLE HDR_AI_FILES (
      FILE_ID    NUMBER         NOT NULL,                  -- the file's number in the Hader server
      APEX_USER  VARCHAR2(255)  NOT NULL,
      CONV_ID    NUMBER,
      NAME       VARCHAR2(200)  NOT NULL,
      MIME       VARCHAR2(100)  NOT NULL,
      CONTENT    BLOB,
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_AI_FILES_PK PRIMARY KEY (FILE_ID))]');
  ddl('HDR_AI_FILES_U_IX', 'CREATE INDEX HDR_AI_FILES_U_IX ON HDR_AI_FILES (APEX_USER, CONV_ID)');
  -- a file an APEX user attaches to a question (a picture, a PDF, a sheet, a ZIP of pictures): kept here until the
  -- Hader server reads it with the question (HDR_UI.ai_upload, ai_ask); it goes with its conversation
  ddl('HDR_AI_UPLOADS', q'[
    CREATE TABLE HDR_AI_UPLOADS (
      UP_ID      NUMBER         NOT NULL,
      APEX_USER  VARCHAR2(255)  NOT NULL,
      REQ_ID     NUMBER,                                   -- the question it was sent with (none yet: still to send)
      NAME       VARCHAR2(200)  NOT NULL,
      MIME       VARCHAR2(100)  NOT NULL,
      BYTES      NUMBER         NOT NULL,
      CONTENT    BLOB,
      DONE       VARCHAR2(1)    DEFAULT 'N' NOT NULL,     -- Y: every part has come (only then is it sent)
      FILE_ID    NUMBER,                                   -- its number in the Hader server, once read there
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_AI_UPLOADS_PK PRIMARY KEY (UP_ID))]');
  ddl('HDR_AI_UPLOADS_U_IX', 'CREATE INDEX HDR_AI_UPLOADS_U_IX ON HDR_AI_UPLOADS (APEX_USER, REQ_ID)');
  ddl('HDR_AI_UPLOADS_R_IX', 'CREATE INDEX HDR_AI_UPLOADS_R_IX ON HDR_AI_UPLOADS (REQ_ID)');

  -- work the background job picks up: EMP (employee or areas changed -> terminals), DEV (a terminal's
  -- area changed -> its people), ALL (rules / timetables / holidays changed -> recalculate from a date)
  ddl('HDR_PENDING', q'[
    CREATE TABLE HDR_PENDING (
      KIND      VARCHAR2(10)   NOT NULL,
      KEY_VAL   VARCHAR2(60)   NOT NULL,
      ADDED     VARCHAR2(4000),
      REMOVED   VARCHAR2(4000),
      DELETED   CHAR(1)        DEFAULT 'N' NOT NULL,
      FROM_DATE DATE,
      MARKED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_PENDING_PK PRIMARY KEY (KIND, KEY_VAL))]');

  -- the interface tables shared with the Hader link (created by hader_interface.sql) get what native mode needs
  col('HDR_EMPLOYEES', 'ATT_SOURCE', 'VARCHAR2(10)');
  col('HDR_EMPLOYEES', 'GENDER', 'VARCHAR2(1)');          -- M / F (the leave types' rules)
  col('HDR_LEAVES', 'RELATION', 'VARCHAR2(10)');          -- the relative a bereavement leave is for (HDR_RELATIONS)
  -- the leave balance movements this edition makes (hader/leave_moves.py): a month's lateness taken from a leave
  ddl('HDR_LEAVE_MOVES', q'[
    CREATE TABLE HDR_LEAVE_MOVES (
      MOVE_ID    NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      MONTH      VARCHAR2(7)    NOT NULL,
      SOURCE     VARCHAR2(10)   DEFAULT 'late' NOT NULL,
      KIND       VARCHAR2(1)    DEFAULT 'D' NOT NULL,
      LEAVE_CODE VARCHAR2(10),
      TITLE      NVARCHAR2(250),
      MINUTES    NUMBER(7)      DEFAULT 0 NOT NULL,
      DAYS       NUMBER(5)      DEFAULT 0 NOT NULL,
      HOURS      NUMBER(3)      DEFAULT 0 NOT NULL,
      MINS       NUMBER(3)      DEFAULT 0 NOT NULL,
      STATUS     VARCHAR2(10)   DEFAULT 'pending' NOT NULL,
      ERROR      VARCHAR2(250),
      POSTED_AT  DATE,
      CREATED_AT DATE           DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_LEAVE_MOVES_PK PRIMARY KEY (MOVE_ID))]');
  -- one employee's month once (the program writes what it posts here too: hader/leave_moves.py)
  ddl('HDR_LEAVE_MOVES_UK', 'CREATE UNIQUE INDEX HDR_LEAVE_MOVES_UK ON HDR_LEAVE_MOVES (MONTH, EMP_CODE, SOURCE)');
  -- the relatives of a bereavement leave and its days for each (the HR system's, hr.table_relations)
  ddl('HDR_RELATIONS', q'[
    CREATE TABLE HDR_RELATIONS (
      REL_CODE VARCHAR2(10)    NOT NULL,
      NAME     NVARCHAR2(250)  NOT NULL,
      DAYS     NUMBER(5,1),
      CONSTRAINT HDR_RELATIONS_PK PRIMARY KEY (REL_CODE))]');
  -- the HR system's limits of an attendance type on its shift (hr.col_*): a month's times and minutes late,
  -- the overtime hours of a month and of a week
  col('HDR_SHIFTS', 'LIM_LATE_TIMES', 'NUMBER(5)');
  col('HDR_SHIFTS', 'LIM_LATE_MIN', 'NUMBER(7)');
  col('HDR_SHIFTS', 'LIM_OT_MONTH', 'NUMBER(7,2)');
  col('HDR_SHIFTS', 'LIM_OT_WEEK', 'NUMBER(7,2)');     -- the HR system's attendance source (hr.source_column)
  col('HADER_PUNCHES', 'WORK_CODE', 'VARCHAR2(20)');
  col('HADER_PUNCHES', 'VERIFY_CODE', 'NUMBER(3)');      -- the terminal's own verify number (for the HR punches table)
  col('HADER_PUNCHES', 'TEMPERATURE', 'NUMBER(4,1)');   -- the body temperature a thermal terminal took
  col('HADER_PUNCHES', 'UPLOADED_AT', 'DATE');         -- reached the server, on the terminal's clock (2.3.7)
  col('HADER_PUNCHES', 'ORIG_TIME', 'DATE');           -- its time before a clock fix (2.3.8)
  col('HADER_PUNCHES', 'FIXED_AT', 'DATE');
  -- a terminal that called in and waits for an administrator to approve it (adms.auto_add = N)
  col('HDR_DEVICES', 'PENDING', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  -- push 3.x firmware keeps a mark for its biometric table (BIODATAStamp); some firmware refuses table queries
  -- (-1004): it is then asked by clearing its marks, so it sends everything by itself (hader/adms/sync.py)
  col('HDR_DEVICES', 'BIO_STAMP', 'VARCHAR2(30)');
  col('HDR_DEVICES', 'NO_QUERY', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  -- the terminal's day it was last asked for the people it holds (once a day, hader/adms/sync.py users_daily)
  col('HDR_DEVICES', 'USERS_DAY', 'VARCHAR2(10)');
  -- 2.3.6: pointed to a server by an administrator: its first call until then is taken from where it comes, and binds it
  col('HDR_DEVICES', 'REBIND_UNTIL', 'DATE');
  -- 2.3.6: an accepted terminal that called from an address it is not bound to: shown for the administrator to accept
  col('HDR_DEVICES', 'MOVED_IP', 'VARCHAR2(45)');
  col('HDR_DEVICES', 'MOVED_AT', 'DATE');
  col('HADER_ATT_DAILY', 'ABSENT_MIN', 'NUMBER(6)');
  -- when a request was decided, and the approver's reason told to the employee (the program's decided_at and
  -- decision_note)
  col('HDR_LEAVES', 'DECIDED_AT', 'DATE');
  col('HDR_LEAVES', 'DECISION_NOTE', 'NVARCHAR2(250)');
  col('HDR_MANUAL_PUNCHES', 'DECIDED_AT', 'DATE');
  col('HDR_MANUAL_PUNCHES', 'DECISION_NOTE', 'NVARCHAR2(250)');
  col('HDR_OVERTIME', 'DECIDED_AT', 'DATE');
  col('HDR_OVERTIME', 'DECISION_NOTE', 'NVARCHAR2(250)');
  -- the employee an alert is about: the bell shows it to those who decide that employee's requests
  col('HDR_NOTIFICATIONS', 'EMP_CODE', 'VARCHAR2(30)');
  -- an account's role in the Hader program and whether it holds every permission there (the users page shows them)
  col('HDR_USERS', 'ROLE_NAME', 'NVARCHAR2(100)');
  col('HDR_USERS', 'IS_SUPER', q'[CHAR(1) DEFAULT 'N' NOT NULL]');
  ddl('HADER_PUNCHES_TIME_IX', 'CREATE INDEX HADER_PUNCHES_TIME_IX ON HADER_PUNCHES (PUNCH_TIME)');
  -- the punches taken lately (by when they were written): the HR punches table looks at the last minutes again,
  -- the Hader server's copy reads them in that order
  ddl('HADER_PUNCHES_CREATED_IX', 'CREATE INDEX HADER_PUNCHES_CREATED_IX ON HADER_PUNCHES (CREATED_AT, PUNCH_ID)');

  -- the same punch twice (same person, time and terminal), found in HADER_PUNCHES when Hader took over a
  -- schema the Hader program had written to: kept here, never lost (HDR_JOBS.activate moves them)
  ddl('HDR_PUNCHES_DUPLICATES', q'[
    CREATE TABLE HDR_PUNCHES_DUPLICATES (
      PUNCH_ID    NUMBER(12)     NOT NULL,
      EMP_CODE    VARCHAR2(30),
      PUNCH_TIME  DATE,
      PUNCH_STATE NUMBER(3),
      STATE_NAME  VARCHAR2(30),
      VERIFY_TYPE VARCHAR2(30),
      DEVICE_SN   VARCHAR2(50),
      DEVICE_NAME VARCHAR2(100),
      SOURCE      VARCHAR2(10),
      CREATED_AT  DATE,
      MOVED_AT    DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_PUNCHES_DUPLICATES_PK PRIMARY KEY (PUNCH_ID))]');
  -- a punch is stored once: the index is made here when HADER_PUNCHES has no such pair, else by HDR_JOBS.activate
  SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = 'HADER_PUNCHES_UK';
  IF n = 0 THEN
    SELECT COUNT(*) INTO n FROM (SELECT 1 FROM HADER_PUNCHES GROUP BY EMP_CODE, PUNCH_TIME, DEVICE_SN HAVING COUNT(*) > 1)
     WHERE ROWNUM = 1;
    IF n = 0 THEN
      EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX HADER_PUNCHES_UK ON HADER_PUNCHES (EMP_CODE, PUNCH_TIME, DEVICE_SN)';
    END IF;
  END IF;

  -- punches the HR system's own punches table (hr_table.*) has not taken yet: waiting for their number to be in
  -- the HR employees table, or refused by the table (its trigger, a column too small) and tried again
  ddl('HDR_HR_HOLD', q'[
    CREATE TABLE HDR_HR_HOLD (
      PUNCH_ID NUMBER(12)     NOT NULL,
      KIND     VARCHAR2(10)   NOT NULL,          -- waiting / refused / clock (a clock gone back to midnight)
      REASON   VARCHAR2(400),
      HELD_AT  DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_HR_HOLD_PK PRIMARY KEY (PUNCH_ID))]');
END;
/
DECLARE
  n NUMBER;
  l_punches NUMBER;
  l_ours NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM HDR_SETTINGS WHERE SKEY = 'native.active';
  IF n = 0 THEN
    SELECT COUNT(*) INTO l_punches FROM HADER_PUNCHES WHERE ROWNUM = 1;
    SELECT COUNT(*) INTO l_ours FROM (SELECT 1 FROM HDR_DEVICES UNION ALL SELECT 1 FROM HDR_EMPLOYEES
                                       UNION ALL SELECT 1 FROM HDR_TRAFFIC) WHERE ROWNUM = 1;
    INSERT INTO HDR_SETTINGS (SKEY, SVALUE)
    VALUES ('native.active', CASE WHEN l_punches > 0 AND l_ours = 0 THEN 'N' ELSE 'Y' END);
    COMMIT;
  END IF;
END;
/
DECLARE
  n     NUMBER;
  l_top NUMBER := 0;
BEGIN
  SELECT COUNT(*) INTO n FROM user_sequences WHERE sequence_name = 'HDR_LOG_SEQ';
  IF n = 0 THEN
    FOR t IN (SELECT 'HDR_TRAFFIC' tab FROM DUAL UNION ALL SELECT 'HDR_ERRLOG' FROM DUAL
              UNION ALL SELECT 'HDR_REJECTS' FROM DUAL UNION ALL SELECT 'HDR_OPLOG' FROM DUAL) LOOP
      EXECUTE IMMEDIATE 'SELECT GREATEST(:1, NVL(MAX(LOG_ID), 0)) FROM ' || t.tab INTO l_top USING l_top;
    END LOOP;
    SELECT GREATEST(l_top, NVL(MAX(LAST_NUMBER), 0)) INTO l_top FROM user_sequences WHERE sequence_name = 'HDR_SEQ';
    -- room for what the code still running during the upgrade logs with HDR_SEQ meanwhile
    EXECUTE IMMEDIATE 'CREATE SEQUENCE HDR_LOG_SEQ START WITH ' || TO_CHAR(l_top + 10000) || ' CACHE 100';
  END IF;
END;
/
DECLARE
  PROCEDURE ddl (p_name IN VARCHAR2, p_sql IN VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM user_objects WHERE object_name = p_name;
    IF n = 0 THEN
      EXECUTE IMMEDIATE p_sql;
    END IF;
  END;
BEGIN
  ddl('HADER_ATT_DAILY_HDR', q'[
    CREATE TABLE HADER_ATT_DAILY_HDR (
      EMP_CODE      VARCHAR2(30)   NOT NULL,
      ATT_DATE      DATE           NOT NULL,
      STATUS        VARCHAR2(20),
      STATUS_AR     VARCHAR2(40),
      STATUS_EN     VARCHAR2(40),
      TIMETABLE     VARCHAR2(60),
      SCHED_IN      DATE,
      SCHED_OUT     DATE,
      CLOCK_IN      DATE,
      CLOCK_OUT     DATE,
      REQUIRED_MIN  NUMBER(6),
      WORKED_MIN    NUMBER(6),
      LATE_MIN      NUMBER(6),
      EARLY_MIN     NUMBER(6),
      OT_MIN        NUMBER(6),
      LEAVE_MIN     NUMBER(6),
      ABSENT_DAYS   NUMBER(5,2),
      ABSENT_MIN    NUMBER(6),
      LEAVE_CODES   VARCHAR2(100),
      HOLIDAY       VARCHAR2(100),
      PUNCHES       VARCHAR2(400),
      UPDATED_AT    DATE DEFAULT SYSDATE NOT NULL,
      WORKDAY       NUMBER(5,2),
      PRESENT       NUMBER(5,2),
      MISSED_IN     NUMBER(2),
      MISSED_OUT    NUMBER(2),
      MISSED_LIST   VARCHAR2(200),
      FIRST_PUNCH   DATE,
      LAST_PUNCH    DATE,
      CONSTRAINT HADER_ATT_DAILY_HDR_PK PRIMARY KEY (EMP_CODE, ATT_DATE))]');
  ddl('HADER_ATT_DAILY_HDR_IX', 'CREATE INDEX HADER_ATT_DAILY_HDR_IX ON HADER_ATT_DAILY_HDR (ATT_DATE, STATUS)');
  ddl('HDR_ENGINE_COMPARE_LOG', q'[
    CREATE TABLE HDR_ENGINE_COMPARE_LOG (
      ATT_DATE      DATE           NOT NULL,
      ROWS_ORACLE   NUMBER(8),
      ROWS_HADER    NUMBER(8),
      ROWS_BOTH     NUMBER(8),
      ONLY_ORACLE   NUMBER(8),
      ONLY_HADER    NUMBER(8),
      ROWS_DIFF     NUMBER(8),
      OK_STATUS     NUMBER(8),
      OK_LATE       NUMBER(8),
      OK_EARLY      NUMBER(8),
      OK_OT         NUMBER(8),
      OK_ABSENT     NUMBER(8),
      OK_WORKED     NUMBER(8),
      TOL_MIN       NUMBER(5),
      LOGGED_AT     DATE DEFAULT SYSDATE NOT NULL,
      CONSTRAINT HDR_ENGINE_COMPARE_LOG_PK PRIMARY KEY (ATT_DATE))]');
END;
/
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM user_tab_columns WHERE table_name = 'HADER_DEV_TERMINALS' AND column_name = 'IS_ATTENDANCE';
  EXECUTE IMMEDIATE 'CREATE OR REPLACE VIEW HDR_V_ATT_TERMINALS AS '
    || q'[SELECT SN, CAST('oracle' AS VARCHAR2(6)) OWNER FROM HDR_DEVICES WHERE IS_ATTENDANCE = 'Y']'
    || CASE WHEN n > 0 THEN q'[ UNION ALL SELECT SN, CAST('hader' AS VARCHAR2(6)) FROM HADER_DEV_TERMINALS WHERE IS_ATTENDANCE = 'Y']' END;
END;
/
CREATE OR REPLACE VIEW HDR_V_ENGINE_COMPARE AS
SELECT x.*,
       CASE WHEN x.IN_ORACLE = 'N' THEN 'only_hader' WHEN x.IN_HADER = 'N' THEN 'only_oracle'
            WHEN x.OK_STATUS || x.OK_LATE || x.OK_EARLY || x.OK_OT || x.OK_ABSENT || x.OK_WORKED = 'YYYYYY' THEN 'match'
            ELSE 'diff' END DIFF_KIND,
       CASE WHEN x.IN_ORACLE = 'Y' AND x.IN_HADER = 'Y' THEN
         LTRIM(CASE WHEN x.OK_STATUS = 'N' THEN ',status' END || CASE WHEN x.OK_LATE = 'N' THEN ',late' END
            || CASE WHEN x.OK_EARLY = 'N' THEN ',early' END || CASE WHEN x.OK_OT = 'N' THEN ',overtime' END
            || CASE WHEN x.OK_ABSENT = 'N' THEN ',absent' END || CASE WHEN x.OK_WORKED = 'N' THEN ',worked' END, ',')
       END DIFF_FIELDS
  FROM (
SELECT NVL(o.EMP_CODE, h.EMP_CODE) EMP_CODE, NVL(o.ATT_DATE, h.ATT_DATE) ATT_DATE,
       CASE WHEN o.EMP_CODE IS NULL THEN 'N' ELSE 'Y' END IN_ORACLE,
       CASE WHEN h.EMP_CODE IS NULL THEN 'N' ELSE 'Y' END IN_HADER,
       o.STATUS O_STATUS, h.STATUS H_STATUS,
       o.LATE_MIN O_LATE, h.LATE_MIN H_LATE, o.EARLY_MIN O_EARLY, h.EARLY_MIN H_EARLY,
       o.OT_MIN O_OT, h.OT_MIN H_OT, o.ABSENT_MIN O_ABSENT, h.ABSENT_MIN H_ABSENT,
       o.WORKED_MIN O_WORKED, h.WORKED_MIN H_WORKED, o.PUNCHES O_PUNCHES, h.PUNCHES H_PUNCHES,
       CASE WHEN NVL(o.STATUS, '~') = NVL(h.STATUS, '~') THEN 'Y' ELSE 'N' END OK_STATUS,
       CASE WHEN ABS(NVL(o.LATE_MIN, 0) - NVL(h.LATE_MIN, 0)) <= t.TOL THEN 'Y' ELSE 'N' END OK_LATE,
       CASE WHEN ABS(NVL(o.EARLY_MIN, 0) - NVL(h.EARLY_MIN, 0)) <= t.TOL THEN 'Y' ELSE 'N' END OK_EARLY,
       CASE WHEN ABS(NVL(o.OT_MIN, 0) - NVL(h.OT_MIN, 0)) <= t.TOL THEN 'Y' ELSE 'N' END OK_OT,
       CASE WHEN ABS(NVL(o.ABSENT_MIN, 0) - NVL(h.ABSENT_MIN, 0)) <= t.TOL THEN 'Y' ELSE 'N' END OK_ABSENT,
       CASE WHEN ABS(NVL(o.WORKED_MIN, 0) - NVL(h.WORKED_MIN, 0)) <= t.TOL THEN 'Y' ELSE 'N' END OK_WORKED
  FROM HADER_ATT_DAILY o
  FULL OUTER JOIN HADER_ATT_DAILY_HDR h ON h.EMP_CODE = o.EMP_CODE AND h.ATT_DATE = o.ATT_DATE
 CROSS JOIN (SELECT NVL(MAX(CASE WHEN REGEXP_LIKE(SVALUE, '^[0-9]{1,4}$') THEN TO_NUMBER(SVALUE) END), 0) TOL
               FROM HDR_SETTINGS WHERE SKEY = 'compare.tol_min') t) x;
CREATE OR REPLACE VIEW HDR_V_RETURN_PUNCHES AS
SELECT r.RETURN_ID, r.SN, r.RETURNED_AT, r.LAST_SEEN, p.PUNCH_ID, p.EMP_CODE, p.PUNCH_TIME, p.UPLOADED_AT
  FROM HDR_RETURNS r
  JOIN HADER_PUNCHES p
    ON p.DEVICE_SN = r.SN
   AND NVL(p.SOURCE, 'device') IN ('device', 'tcp')
   AND p.ORIG_TIME IS NULL
   AND p.UPLOADED_AT BETWEEN r.RETURNED_AT - 1 / 1440 AND r.RETURNED_AT + 1 / 24
   AND p.PUNCH_TIME >= TRUNC(r.RETURNED_AT)
   AND p.PUNCH_TIME < r.RETURNED_AT - 15 / 1440
   AND p.PUNCH_TIME < TRUNC(r.RETURNED_AT) + (r.RETURNED_AT - r.LAST_SEEN)
 WHERE r.STATUS = 'open';
CREATE OR REPLACE VIEW HDR_V_SETTINGS AS
SELECT SKEY, SVALUE FROM HDR_SETTINGS
 WHERE SKEY <> 'adms.gate_key' AND NOT REGEXP_LIKE(LOWER(SKEY), '(key|secret|password|passwd|token)$');
CREATE OR REPLACE VIEW HDR_V_POLICY_VERSIONS AS
SELECT 'timetable' AS SCOPE, v.TT_ID AS TARGET_ID, t.ALIAS AS TARGET_NAME, v.VER_ID, v.VER_KIND,
       v.EFFECTIVE_FROM AS DATE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_TIMETABLE_VERSIONS x
         WHERE x.TT_ID = v.TT_ID AND x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1 AS DATE_TO,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_TIMETABLE_VERSIONS x LEFT JOIN HDR_TIMETABLE_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.TT_ID = v.TT_ID AND x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END AS APPLIED,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_TIMETABLE_VERSIONS v
  LEFT JOIN HDR_TIMETABLE_VERSIONS vc ON vc.VER_ID = v.CLOSES
  LEFT JOIN HDR_TIMETABLES t ON t.TT_ID = v.TT_ID
UNION ALL
SELECT 'shift', v.SHIFT_ID, s.ALIAS, v.VER_ID, v.VER_KIND, v.EFFECTIVE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_SHIFT_VERSIONS x
         WHERE x.SHIFT_ID = v.SHIFT_ID AND x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_SHIFT_VERSIONS x LEFT JOIN HDR_SHIFT_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.SHIFT_ID = v.SHIFT_ID AND x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_SHIFT_VERSIONS v
  LEFT JOIN HDR_SHIFT_VERSIONS vc ON vc.VER_ID = v.CLOSES
  LEFT JOIN HDR_SHIFTS s ON s.SHIFT_ID = v.SHIFT_ID
UNION ALL
SELECT 'rules', 0, CAST(NULL AS NVARCHAR2(60)), v.VER_ID, v.VER_KIND, v.EFFECTIVE_FROM,
       (SELECT MIN(x.EFFECTIVE_FROM) FROM HDR_RULE_VERSIONS x WHERE x.EFFECTIVE_FROM > v.EFFECTIVE_FROM) - 1,
       CASE WHEN EXISTS (
         SELECT 1 FROM HDR_RULE_VERSIONS x LEFT JOIN HDR_RULE_VERSIONS xc ON xc.VER_ID = x.CLOSES
          WHERE x.EFFECTIVE_FROM = v.EFFECTIVE_FROM AND x.VER_ID <> v.VER_ID
            AND ((x.VER_KIND <> 'return' AND (v.VER_KIND = 'return' OR x.VER_ID > v.VER_ID))
                 OR (x.VER_KIND = 'return' AND v.VER_KIND = 'return'
                     AND (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') < NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                          OR (NVL(xc.EFFECTIVE_FROM, DATE '0001-01-01') = NVL(vc.EFFECTIVE_FROM, DATE '0001-01-01')
                              AND (x.CLOSES < v.CLOSES OR (x.CLOSES = v.CLOSES AND x.VER_ID > v.VER_ID)))))))
       THEN 'N' ELSE 'Y' END,
       v.CLOSES, v.CHANGED, v.REASON, v.ACTOR, v.CREATED_AT
  FROM HDR_RULE_VERSIONS v
  LEFT JOIN HDR_RULE_VERSIONS vc ON vc.VER_ID = v.CLOSES;
CREATE OR REPLACE TRIGGER HDR_LEAVE_MOVES_BI BEFORE INSERT ON HDR_LEAVE_MOVES FOR EACH ROW
BEGIN
  IF :NEW.MOVE_ID IS NULL THEN :NEW.MOVE_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_AREAS_BI BEFORE INSERT ON HDR_AREAS FOR EACH ROW
BEGIN
  IF :NEW.AREA_ID IS NULL THEN :NEW.AREA_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
CREATE OR REPLACE TRIGGER HDR_EMPLOYEES_BI BEFORE INSERT OR UPDATE ON HDR_EMPLOYEES FOR EACH ROW
BEGIN
  IF INSERTING AND :NEW.EMP_ID IS NULL THEN :NEW.EMP_ID := HDR_SEQ.NEXTVAL; END IF;
  IF (INSERTING OR :NEW.EMP_CODE <> :OLD.EMP_CODE)
     AND NOT NVL(REGEXP_LIKE(:NEW.EMP_CODE, '^[0-9A-Za-z][0-9A-Za-z_-]{0,23}$'), FALSE) THEN
    RAISE_APPLICATION_ERROR(-20608, UNISTR('\0631\0642\0645 \0645\0648\0638\0641 \063A\064A\0631 \0635\0627\0644\062D / invalid employee number'));
  END IF;
  :NEW.UPDATED_AT := SYSDATE;
END;
/
CREATE OR REPLACE TRIGGER HDR_BIO_BI BEFORE INSERT ON HDR_BIO FOR EACH ROW
BEGIN
  IF :NEW.BIO_ID IS NULL THEN :NEW.BIO_ID := HDR_SEQ.NEXTVAL; END IF;
END;
/
